-- 9AM Crew: Court6 Cycle 1 (2026-10-19, 9 weeks). Generated by supabase/cycle1.py.
-- Safe to run again: it updates this cycle and overwrites these days in place.
-- Fails without changing anything if a different cycle covers these weeks.
begin;
update public.cycles set week_count = 9, why = 'Nine weeks, Monday to Friday: test, three Base weeks, two Build weeks, a primer/deload week, a retest week and a flex week. Week 1 tests a 3RM back squat and deadlift, a 5RM strict press and a 1 km run (or 1,000 m row); every lift percentage comes from estimated max (3RM × 1.06, press 5RM × 1.13) with an RPE 8 cap, and every run pace comes from the 1 km time. Monday and Friday are the hard days, Wednesday is steady threshold work, Thursday is easy, the lift always comes before conditioning, and class running rises no more than 10% a week. stations live in Wednesday conditioning, compromised running starts in Week 5, and toes-to-bar is the block skill (baseline Week 2, retest Week 9). Week 8 repeats the Week 1 tests on the same days, and the Week 8 numbers plus the Week 9 Helen, Mini Challenge and strict pull-up baselines become the next block''s starting points.', goals = array['Raise 3RM back squat and deadlift and 5RM strict press', 'Faster 1 km run or 1,000 m row', 'First or more unbroken toes-to-bar', 'Learn the stations and running off them']::text[], weeks = '[{"kind": "test", "label": "Test", "pct": 0, "sets": 0, "reps": 3}, {"kind": "build", "label": "Base", "pct": 65, "sets": 4, "reps": 8}, {"kind": "build", "label": "Base", "pct": 70, "sets": 5, "reps": 6}, {"kind": "build", "label": "Base", "pct": 75, "sets": 5, "reps": 5}, {"kind": "build", "label": "Build", "pct": 80, "sets": 5, "reps": 3}, {"kind": "build", "label": "Build", "pct": 85, "sets": 3, "reps": 3}, {"kind": "deload", "label": "Primer", "pct": 85, "sets": 1, "reps": 2}, {"kind": "test", "label": "Retest", "pct": 0, "sets": 0, "reps": 3}, {"kind": "build", "label": "Flex", "pct": 65, "sets": 3, "reps": 5}]'::jsonb, days = '{"1": {"focus": "Squat · intervals · hard", "style": "intervals", "lift": "Back squat", "gentle": "Goblet squat", "skill": null, "notes": "Heavy back squat, then short bike or row intervals. No running on squat day."}, "2": {"focus": "Toes-to-bar · aerobic intervals · moderate", "style": "long", "lift": null, "gentle": null, "skill": null, "notes": "Toes-to-bar skill block, then the week''s main aerobic running. 1 km test and retest live here (Wk 1 and 8)."}, "3": {"focus": "Deadlift · threshold · sustain", "style": "amrap", "lift": "Deadlift", "gentle": "Kettlebell deadlift", "skill": null, "notes": "Deadlift, then threshold work at about 7/10 on stations; compromised running in Weeks 5–6."}, "4": {"focus": "Accessory strength · easy intervals · easy", "style": "easy", "lift": null, "gentle": null, "skill": null, "notes": "Easy day: accessory supersets and core, then easy row/bike intervals with set work and rest."}, "5": {"focus": "Clean + press · short workout · hard", "style": "short", "lift": "Strict press", "gentle": "Dumbbell press", "skill": null, "notes": "Power clean technique, then strict press, then a short hard workout. Cindy Wk 4, Mini Challenge Wk 9."}}'::jsonb, updated_at = now() where start_date = '2026-10-19' and name = 'Strength + Aerobic Base';
insert into public.cycles (start_date, week_count, name, why, brief, goals, weeks, days, created_by) select '2026-10-19', 9, 'Strength + Aerobic Base', 'Nine weeks, Monday to Friday: test, three Base weeks, two Build weeks, a primer/deload week, a retest week and a flex week. Week 1 tests a 3RM back squat and deadlift, a 5RM strict press and a 1 km run (or 1,000 m row); every lift percentage comes from estimated max (3RM × 1.06, press 5RM × 1.13) with an RPE 8 cap, and every run pace comes from the 1 km time. Monday and Friday are the hard days, Wednesday is steady threshold work, Thursday is easy, the lift always comes before conditioning, and class running rises no more than 10% a week. stations live in Wednesday conditioning, compromised running starts in Week 5, and toes-to-bar is the block skill (baseline Week 2, retest Week 9). Week 8 repeats the Week 1 tests on the same days, and the Week 8 numbers plus the Week 9 Helen, Mini Challenge and strict pull-up baselines become the next block''s starting points.', '', array['Raise 3RM back squat and deadlift and 5RM strict press', 'Faster 1 km run or 1,000 m row', 'First or more unbroken toes-to-bar', 'Learn the stations and running off them']::text[], '[{"kind": "test", "label": "Test", "pct": 0, "sets": 0, "reps": 3}, {"kind": "build", "label": "Base", "pct": 65, "sets": 4, "reps": 8}, {"kind": "build", "label": "Base", "pct": 70, "sets": 5, "reps": 6}, {"kind": "build", "label": "Base", "pct": 75, "sets": 5, "reps": 5}, {"kind": "build", "label": "Build", "pct": 80, "sets": 5, "reps": 3}, {"kind": "build", "label": "Build", "pct": 85, "sets": 3, "reps": 3}, {"kind": "deload", "label": "Primer", "pct": 85, "sets": 1, "reps": 2}, {"kind": "test", "label": "Retest", "pct": 0, "sets": 0, "reps": 3}, {"kind": "build", "label": "Flex", "pct": 65, "sets": 3, "reps": 5}]'::jsonb, '{"1": {"focus": "Squat · intervals · hard", "style": "intervals", "lift": "Back squat", "gentle": "Goblet squat", "skill": null, "notes": "Heavy back squat, then short bike or row intervals. No running on squat day."}, "2": {"focus": "Toes-to-bar · aerobic intervals · moderate", "style": "long", "lift": null, "gentle": null, "skill": null, "notes": "Toes-to-bar skill block, then the week''s main aerobic running. 1 km test and retest live here (Wk 1 and 8)."}, "3": {"focus": "Deadlift · threshold · sustain", "style": "amrap", "lift": "Deadlift", "gentle": "Kettlebell deadlift", "skill": null, "notes": "Deadlift, then threshold work at about 7/10 on stations; compromised running in Weeks 5–6."}, "4": {"focus": "Accessory strength · easy intervals · easy", "style": "easy", "lift": null, "gentle": null, "skill": null, "notes": "Easy day: accessory supersets and core, then easy row/bike intervals with set work and rest."}, "5": {"focus": "Clean + press · short workout · hard", "style": "short", "lift": "Strict press", "gentle": "Dumbbell press", "skill": null, "notes": "Power clean technique, then strict press, then a short hard workout. Cindy Wk 4, Mini Challenge Wk 9."}}'::jsonb, null where not exists (select 1 from public.cycles where start_date = '2026-10-19' and name = 'Strength + Aerobic Base');
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-19', 'Squat Test + Bike Intervals', 'Squat test · bike intervals', 'Find the most you can squat for 3 good reps. It sets your squat weights for the next few weeks. Then short, fast intervals to open up the lungs.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["2 rounds: 200 m easy row · 10 air squats · 10 band pull-aparts · 5 inchworms\nThen: 10 goblet squats with a 3 s pause · 10 band side-steps each way · 10 empty-bar back squats", "2 rounds: 200 m easy row · 10 air squats · 10 band pull-aparts · 5 inchworms\nThen: 10 goblet squats with a 3 s pause · 10 band side-steps each way · 10 empty-bar back squats", "2 rounds: 200 m easy row · 10 air squats · 10 band pull-aparts · 5 inchworms\nThen: 10 goblet squats with a 3 s pause · 10 band side-steps each way · 10 empty-bar back squats", "2 rounds: 200 m easy row · 10 air squats · 10 band pull-aparts · 5 inchworms\nThen: 10 goblet squats with a 3 s pause · 10 band side-steps each way · 10 empty-bar back squats"]}, {"kind": "strength", "label": "Strength", "title": "Squat test: heavy 3", "minutes": 20, "lift": {"movement": "Back squat", "gentleMovement": "Goblet squat", "mode": "build", "sets": 1, "reps": 3, "pct": [null, null, null, null], "note": "Week 1 3RM × 1.06 = e1RM for squat %."}, "versions": ["Goblet squat: build to a heavy 3 (18 min)\nLight × 8, then 3 sets of 3 getting heavier, then 2–4 tries at 3. Stop with 2 reps left.\nWrite down your best 3 (lb).", "Back squat: build to a heavy 3 (18 min)\nEmpty bar × 8, then build in small jumps, then 2–4 tries at 3, adding 5–10 lb each time.\nCoach calls the set if depth or position breaks. Write down your best 3 (lb).", "Back squat: build to a heavy 3 (18 min)\nEmpty bar × 8, then build in small jumps, then 2–4 tries at 3, adding 5–15 lb each time.\nCoach calls the set if depth or position breaks. Write down your best 3 (lb).", "Back squat: build to a heavy 3 (18 min)\nEmpty bar × 8, then build in small jumps, then 2–4 tries at 3, adding 5–20 lb each time.\nCoach calls the set if depth or position breaks. Write down your best 3 (lb)."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Bike intervals", "minutes": 13, "versions": ["6 rounds: 0:30 hard, 1:30 easy (12 min)\nBike or rower, whichever feels easier. Hard but comfortable; hard pieces can be 0:20. Same machine every round.\nNo machine free? Fast marching, then slow walk.", "6 rounds: 0:30 hard, 1:30 easy (12 min)\nAny machine, same one all 6 rounds. Hard but smooth.\nNo machine free? Jumping jacks, then walk.", "6 rounds: 0:30 hard, 1:30 easy (12 min)\nRower, all 6 rounds. Hard, but keep good form.\nNo rower free? Fast single-unders or high knees, then walk.", "6 rounds: 0:30 hard, 1:30 easy (12 min)\nAir bike, all 6 rounds. Close to all-out.\nNo bike free? All-out single-unders or high knees, then walk."]}, {"kind": "skill", "label": "Accessory", "title": "Accessory superset", "minutes": 5, "versions": ["2 rounds: 6 split squats each side, holding the rig, short range · 15 s side plank each side, from the knees\nLeave 3–4 reps in the tank.", "2 rounds: 10 bodyweight split squats each side (hold the rig if needed) · 30 s side plank each side, from the knees\nLeave 3 reps in the tank.", "2 rounds: 10 light dumbbell split squats each side · 30 s side plank each side\nLeave 3 reps in the tank.", "2 rounds: 10 light dumbbell split squats each side · 30 s side plank each side\nLeave 3 reps in the tank."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + log", "minutes": 7, "versions": ["3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads and write your best 3 on your scorecard.", "3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads and write your best 3 on your scorecard.", "3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads and write your best 3 on your scorecard.", "3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads and write your best 3 on your scorecard."]}]'::jsonb, 'published', null)
