insert into public.workout_coach_notes (class_date, body) values ('2026-10-19', 'Two coaches on test days if possible. Watch depth and back position; you call the set. Steady, Strong and Full test the barbell back squat (smaller jumps at Steady); only Gentle tests the goblet squat. Machine-only intervals: Monday has no running on purpose (heavy-leg day), so no outside version.
Scaling: Gentle warm-up: step instead of jump, walk instead of jog, comfortable range. Newer lifters / first 4 weeks after on-ramp: start with the empty bar (or lighter training bar), no max attempt; stop at the first RPE 8 set and record that. Masters (40+): RPE 8 max on the interval hard pieces. Knee or back pain: air bike only.
Test: stop at RPE 8 (2 reps left), no RPE 9–10 grinders. Gentle: one DB or KB at the chest, box for depth if needed. Record load in lb, level, coach notes. Week 1 3RM × 1.06 = e1RM for every squat % this block.
Intervals: hard pieces Gentle RPE 6 (can be 0:20), Steady RPE 7, Strong RPE 8, Full RPE 9. Same machine all 6 rounds. Cap 12:00 (fixed) · Aim: hold calories within 10% from round 1 to round 6 · Feel: gas · Pace: reach. No machine: score = reps instead of calories.
No machine (warm-up/cool-down): easy jumping jacks, marching or jump rope, about 1:00 per 250 m or per 5 cal.
Ladder: Bar × 8, ~50% × 5, ~65% × 3, ~75% × 3.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-20', '1 km Test + Toes-to-Bar', '1 km test · toes-to-bar', 'Our one run test: your 1 km time sets your run and row paces for the next few weeks. Toes-to-bar work stays light today.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["400 m easy jog (or 500 m row) · leg swings · 2 × 20 m A-skips\nThen: 2 × (10 hollow rocks + 10 arch rocks) · 10 scap pull-ups · 2 × 100 m build-up strides", "400 m easy jog (or 500 m row) · leg swings · 2 × 20 m A-skips\nThen: 2 × (10 hollow rocks + 10 arch rocks) · 10 scap pull-ups · 2 × 100 m build-up strides", "400 m easy jog (or 500 m row) · leg swings · 2 × 20 m A-skips\nThen: 2 × (10 hollow rocks + 10 arch rocks) · 10 scap pull-ups · 2 × 100 m build-up strides", "400 m easy jog (or 500 m row) · leg swings · 2 × 20 m A-skips\nThen: 2 × (10 hollow rocks + 10 arch rocks) · 10 scap pull-ups · 2 × 100 m build-up strides"]}, {"kind": "skill", "label": "Skill", "title": "Toes-to-bar practice", "minutes": 13, "versions": ["Toes-to-bar level 1: every 2 min × 4\n15 s tuck hollow hold · 15 s superman hold, arms by your sides · 4 lying bent-knee raises · 5 ring rows on a high bar, body nearly upright\nLight work, not a test.", "Toes-to-bar level 1: every 2 min × 4\n20 s tuck hollow hold · 20 s superman hold · 5 lying leg raises · 6 ring rows, body upright\nLight work, not a test.", "Toes-to-bar level 1: every 2 min × 4\n20 s hollow hold · 20 s superman hold · 5 hanging knee raises · 5 ring rows, feet forward\nLight work, not a test.", "Toes-to-bar level 1: every 2 min × 4\n20 s hollow hold · 20 s superman hold · 5 hanging knee raises · 3 strict pull-ups (band if needed), 3 s down\nLight work, not a test."]}, {"kind": "conditioning", "label": "Test", "title": "1,000 m row test", "minutes": 15, "versions": ["1,000 m row, steady and comfortable-hard. A short pause at 500 m is fine (note it).\nThen walk and drink water, 8–10 min.\nWrite down your time and whether you ran or rowed.\nNo rower free? Wait for the next one, or run 1 km outside if safe.", "1,000 m row, as fast as you can hold the whole way.\nThen walk and drink water, 8–10 min.\nWrite down your time and whether you ran or rowed.\nNo rower free? Wait for the next one, or run 1 km outside if safe.", "1,000 m row at an even pace.\nThen walk and drink water, 8–10 min.\nWrite down your time and whether you ran or rowed.\nNo rower free? Wait for the next one, or run 1 km outside if safe.", "1,000 m row, hard but even: same split every 250 m.\nThen walk and drink water, 8–10 min.\nWrite down your time and whether you ran or rowed.\nNo rower free? Wait for the next one, or run 1 km outside if safe."], "outdoor": {"title": "1 km run test", "versions": ["1 km walk/jog: jog 1 min, walk 1 min, repeat (or brisk walk all the way). Keep the same plan in Week 8.\nThen walk and drink water, 8–10 min.\nWrite down your time and whether you ran or rowed.", "1 km run/walk, as fast as you can hold the whole way.\nThen walk and drink water, 8–10 min.\nWrite down your time and whether you ran or rowed.", "1 km run at an even pace.\nThen walk and drink water, 8–10 min.\nWrite down your time and whether you ran or rowed.", "1 km run, hard but even: same pace every 200 m.\nThen walk and drink water, 8–10 min.\nWrite down your time and whether you ran or rowed."]}}, {"kind": "conditioning", "label": "Conditioning", "title": "Easy flush", "minutes": 13, "versions": ["3 rounds, easy, not for time (12 min):\n1 min step-jacks or marching on the spot · 8 incline push-ups (box or wall) · 8 air squats to a box\nTalk-able pace the whole time.", "3 rounds, easy, not for time (12 min):\n1 min easy jumping jacks or single-unders · 8 incline push-ups (hands on a box) · 12 air squats\nTalk-able pace the whole time.", "3 rounds, easy, not for time (12 min):\n1:30 easy single-unders (break when you like) · 10 push-ups (knees if needed) · 15 air squats\nTalk-able pace the whole time.", "3 rounds, easy, not for time (12 min):\n1:30 easy single-unders (break when you like) · 10 push-ups · 15 air squats\nTalk-able pace the whole time."], "outdoor": {"title": "Easy run flush", "versions": ["3 rounds, easy, not for time (12 min):\n300 m walk/jog · 8 incline push-ups (box or wall) · 8 air squats to a box\nTalk-able pace the whole time.", "3 rounds, easy, not for time (12 min):\n400 m easy run/walk · 8 incline push-ups (hands on a box) · 12 air squats\nTalk-able pace the whole time.", "3 rounds, easy, not for time (12 min):\n400 m easy run · 10 push-ups (knees if needed) · 15 air squats\nTalk-able pace the whole time.", "3 rounds, easy, not for time (12 min):\n400 m easy run · 10 push-ups · 15 air squats\nTalk-able pace the whole time."]}}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["Walk 2 min · calf and hamstring stretch 1 min each side · lat stretch on the rig 1 min", "Walk 2 min · calf and hamstring stretch 1 min each side · lat stretch on the rig 1 min", "Walk 2 min · calf and hamstring stretch 1 min each side · lat stretch on the rig 1 min", "Walk 2 min · calf and hamstring stretch 1 min each side · lat stretch on the rig 1 min"]}]'::jsonb, 'published', null)
