insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-21', 'Deadlift Test + Easy Bike', 'Deadlift test · easy bike', 'Find the most you can deadlift for 3 good reps. It sets your deadlift weights for the next few weeks. Then an easy bike workout to move and breathe.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["2 rounds: 250 m easy row · 10 PVC good mornings · 10 bird dogs · 5 push-ups\nThen: 10 kettlebell deadlifts · 8 empty-bar Romanian deadlifts", "2 rounds: 250 m easy row · 10 PVC good mornings · 10 bird dogs · 5 push-ups\nThen: 10 kettlebell deadlifts · 8 empty-bar Romanian deadlifts", "2 rounds: 250 m easy row · 10 PVC good mornings · 10 bird dogs · 5 push-ups\nThen: 10 kettlebell deadlifts · 8 empty-bar Romanian deadlifts", "2 rounds: 250 m easy row · 10 PVC good mornings · 10 bird dogs · 5 push-ups\nThen: 10 kettlebell deadlifts · 8 empty-bar Romanian deadlifts"]}, {"kind": "strength", "label": "Strength", "title": "Deadlift test: heavy 3", "minutes": 18, "lift": {"movement": "Deadlift", "gentleMovement": "Kettlebell deadlift", "mode": "build", "sets": 1, "reps": 3, "pct": [null, null, null, null], "note": "Week 1 3RM × 1.06 = e1RM for deadlift %."}, "versions": ["Kettlebell deadlift: build to a heavy 3 (16 min)\nLight × 5, then 3 sets of 3 getting heavier, then 2–4 tries at 3. Stop with 2 reps left. Reset each rep.\nWrite down your best 3 (lb).", "Deadlift: build to a heavy 3 (16 min)\n40% × 5, 55% × 3, 65% × 3, 75% × 3, then 2–4 tries at 3, adding 5–15 lb each time.\nReset each rep. Coach stops the set if your back rounds. Write down your best 3 (lb).", "Deadlift: build to a heavy 3 (16 min)\n40% × 5, 55% × 3, 65% × 3, 75% × 3, then 2–4 tries at 3, adding 10–20 lb each time.\nReset each rep. Coach stops the set if your back rounds. Write down your best 3 (lb).", "Deadlift: build to a heavy 3 (16 min)\n40% × 5, 55% × 3, 65% × 3, 75% × 3, then 2–4 tries at 3, adding 10–30 lb each time.\nReset each rep. Coach stops the set if your back rounds. Write down your best 3 (lb)."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Easy bike EMOM", "minutes": 14, "versions": ["Every minute, 3 rounds (12 min), easy, not for score:\nMin 1 + 3: 0:30 very easy air bike\nMin 2: 6 reverse lunges each side (hold the rig) or step-backs\nMin 4: 10 m hands-and-knees crawl + 8 glute bridges\nNo bike free? Step-jacks or march.", "Every minute, 3 rounds (12 min), easy, not for score:\nMin 1 + 3: 0:40 easy air bike\nMin 2: 8 reverse lunges each side\nMin 4: 15 m bear crawl + 10 glute bridges\nNo bike free? Easy jumping jacks.", "Every minute, 3 rounds (12 min), easy, not for score:\nMin 1 + 3: 0:40 easy air bike\nMin 2: 8 reverse lunges each side\nMin 4: 20 m bear crawl + 10 glute bridges\nNo bike free? Easy single-unders.", "Every minute, 3 rounds (12 min), easy, not for score:\nMin 1 + 3: 0:40 easy air bike\nMin 2: 10 reverse lunges each side\nMin 4: 20 m bear crawl + 12 glute bridges\nNo bike free? Easy single-unders."]}, {"kind": "skill", "label": "Accessory", "title": "Core", "minutes": 6, "versions": ["2 rounds: 6 dead bugs each side, arms only · 15 s side plank each side, from the knees", "2 rounds: 10 dead bugs each side · 20 s side plank each side, from the knees", "2 rounds: 10 dead bugs each side · 20 s side plank each side", "2 rounds: 10 dead bugs each side · 20 s side plank each side"]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + log", "minutes": 8, "versions": ["3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s\nWrite your best 3 on your scorecard.", "3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s\nWrite your best 3 on your scorecard.", "3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s\nWrite your best 3 on your scorecard.", "3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s\nWrite your best 3 on your scorecard."]}]'::jsonb, 'published', null)
