insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-22', 'Easy Day: Strength + Row/Bike', 'Accessory strength · easy intervals', 'The easy day: strength work for joints and posture, then easy row and bike pieces. Your coach also checks how you move, to set up your level.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 7, "versions": ["2 min easy bike or row · 10 90/90 hip switches · 5 world''s greatest stretch each side\nThen: 5 light single-leg Romanian deadlifts each side · 10 band pull-aparts", "2 min easy bike or row · 10 90/90 hip switches · 5 world''s greatest stretch each side\nThen: 5 light single-leg Romanian deadlifts each side · 10 band pull-aparts", "2 min easy bike or row · 10 90/90 hip switches · 5 world''s greatest stretch each side\nThen: 5 light single-leg Romanian deadlifts each side · 10 band pull-aparts", "2 min easy bike or row · 10 90/90 hip switches · 5 world''s greatest stretch each side\nThen: 5 light single-leg Romanian deadlifts each side · 10 band pull-aparts"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory strength + core", "minutes": 21, "versions": ["2 rounds, leave 4 reps in the tank:\n8 light chest-supported dumbbell rows (incline bench) · 8 two-leg Romanian deadlifts, light dumbbells, short range · 6 dead bugs each side, arms only", "2 rounds, leave 3 reps in the tank:\n10 light dumbbell bent-over rows · 8 single-leg Romanian deadlifts each side, holding the rig (light dumbbell or none) · 10 dead bugs each side", "2 rounds, leave 3 reps in the tank:\n10 dumbbell bent-over rows · 8 single-leg Romanian deadlifts each side, light dumbbell · 10 dead bugs each side", "2 rounds, leave 3 reps in the tank:\n10 dumbbell bent-over rows · 8 single-leg Romanian deadlifts each side, light dumbbell · 10 dead bugs each side"]}, {"kind": "conditioning", "label": "Conditioning", "title": "Easy row/bike intervals", "minutes": 21, "versions": ["4 rounds: 4 min easy, 1 min rest (19 min). Switch between row and air bike each round.\nVery easy: talk in full sentences. Rounds can be 1–2 min shorter.\nNo machine free? 1 min each: marching · low step-ups · wall push-ups. Repeat.", "4 rounds: 4 min easy, 1 min rest (19 min). Switch between row and air bike each round.\nEasy and chatty: talk in full sentences. Rounds can be 1 min shorter.\nNo machine free? 1 min each: low box step-ups · jumping jacks · air squats. Repeat.", "4 rounds: 4 min easy, 1 min rest (19 min). Switch between row and air bike each round.\nEasy: talk in full sentences; slow down if you can''t.\nNo machine free? 1 min each: step-ups · jumping jacks · air squats · easy single-unders. Repeat.", "4 rounds: 4 min easy, 1 min rest (19 min). Switch between row and air bike each round.\nEasy but steady: talk in full sentences; slow down if you can''t.\nNo machine free? 1 min each: step-ups · jumping jacks · air squats · easy single-unders. Repeat."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + mobility", "minutes": 8, "versions": ["3 min easy bike · hip flexor and hamstring stretch 1 min each side · 1 min deep-squat hold", "3 min easy bike · hip flexor and hamstring stretch 1 min each side · 1 min deep-squat hold", "3 min easy bike · hip flexor and hamstring stretch 1 min each side · 1 min deep-squat hold", "3 min easy bike · hip flexor and hamstring stretch 1 min each side · 1 min deep-squat hold"]}]'::jsonb, 'published', null)
