insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-23', 'Press Test + Station AMRAP', 'Press test · stations', 'Find the most you can strict press for 5 good reps. Then a first, steady look at four stations you''ll repeat in week 8.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["3 min easy bike · 10 PVC pass-throughs · 10 PVC overhead squats\nThen: barbell drills × 5 each (down-and-up, high elbows, muscle clean, hang power clean) · 10 empty-bar strict presses", "3 min easy bike · 10 PVC pass-throughs · 10 PVC overhead squats\nThen: barbell drills × 5 each (down-and-up, high elbows, muscle clean, hang power clean) · 10 empty-bar strict presses", "3 min easy bike · 10 PVC pass-throughs · 10 PVC overhead squats\nThen: barbell drills × 5 each (down-and-up, high elbows, muscle clean, hang power clean) · 10 empty-bar strict presses", "3 min easy bike · 10 PVC pass-throughs · 10 PVC overhead squats\nThen: barbell drills × 5 each (down-and-up, high elbows, muscle clean, hang power clean) · 10 empty-bar strict presses"]}, {"kind": "strength", "label": "Strength", "title": "Press test: heavy 5", "minutes": 17, "lift": {"movement": "Strict press", "gentleMovement": "Dumbbell press", "mode": "build", "sets": 1, "reps": 5, "pct": [null, null, null, null], "note": "Week 1 5RM × 1.13 = e1RM for press %."}, "versions": ["Seated dumbbell press: build to a heavy 5 (15 min)\nBack against a bench. Light × 10, then 2 sets of 5 getting heavier, then 2–4 tries at 5. Stop with 2 reps left.\nWrite down the weight per hand (lb).", "Strict press: build to a heavy 5 (15 min)\nEmpty bar × 10, then build in small jumps, then 2–4 tries at 5, adding 2.5–5 lb each time.\nNo leg drive, ribs down. Write down your best 5 (lb).", "Strict press: build to a heavy 5 (15 min)\nEmpty bar × 10, then build in small jumps, then 2–4 tries at 5, adding 5 lb each time.\nNo leg drive, ribs down. Write down your best 5 (lb).", "Strict press: build to a heavy 5 (15 min)\nEmpty bar × 10, then build in small jumps, then 2–4 tries at 5, adding 5–10 lb each time.\nNo leg drive, ribs down. Write down your best 5 (lb)."]}, {"kind": "conditioning", "label": "Test", "title": "Station AMRAP", "minutes": 16, "versions": ["Learn the stations (4 min). Then 10 min, as many rounds as you can, steady:\n10 wall balls (4/6 lb, 7 ft target) · 20 m farmers carry 2 × 13/18 lb · 10 low step-ups (total) · 4 incline step-back burpees + 2 long strides\nWrite down rounds + reps. Redo in week 8.", "Learn the stations (4 min). Then 10 min, as many rounds as you can, steady:\n10 wall balls (6/10 lb, lower target) · 20 m farmers carry 2 × 18/26 lb · 10 bodyweight lunges (total) · 4 step-back burpees + broad jump\nWrite down rounds + reps. Redo in week 8.", "Learn the stations (4 min). Then 10 min, as many rounds as you can, steady:\n10 wall balls (6/10 lb) · 20 m farmers carry 2 × 26/35 lb · 10 sandbag lunges (22/33 lb, total) · 4 burpee broad jumps\nWrite down rounds + reps. Redo in week 8.", "Learn the stations (4 min). Then 10 min, as many rounds as you can, steady:\n10 wall balls (10/14 lb) · 20 m farmers carry 2 × 35/53 lb · 10 sandbag lunges (22/44 lb, total) · 4 burpee broad jumps\nWrite down rounds + reps. Redo in week 8."]}, {"kind": "skill", "label": "Accessory", "title": "Accessory superset", "minutes": 4, "versions": ["2 rounds: 8 light dumbbell rear-delt flys, chest on an incline bench · 6 lying bent-knee raises\nLeave 3–4 reps in the tank.", "2 rounds: 10 light dumbbell rear-delt flys · 8 lying leg raises\nLeave 3 reps in the tank.", "2 rounds: 10 dumbbell rear-delt flys · 8 hanging knee raises\nLeave 3 reps in the tank.", "2 rounds: 10 dumbbell rear-delt flys · 8 hanging knee raises\nLeave 3 reps in the tank."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 8, "versions": ["3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min", "3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min", "3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min", "3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min"]}]'::jsonb, 'published', null)
