insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-26', 'Squat + Row EMOM', 'Squat · intervals', 'Plenty of squat sets at a moderate weight, then short intervals you repeat every minute.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["2 rounds (5 min): 200 m easy row · 10 air squats · 10 band pull-aparts · 5 inchworms\nThen (6 min): 10 goblet squats with a 3 s pause · 10 band side-steps each way · 10 empty-bar back squats", "2 rounds (5 min): 200 m easy row · 10 air squats · 10 band pull-aparts · 5 inchworms\nThen (6 min): 10 goblet squats with a 3 s pause · 10 band side-steps each way · 10 empty-bar back squats", "2 rounds (5 min): 200 m easy row · 10 air squats · 10 band pull-aparts · 5 inchworms\nThen (6 min): 10 goblet squats with a 3 s pause · 10 band side-steps each way · 10 empty-bar back squats", "2 rounds (5 min): 200 m easy row · 10 air squats · 10 band pull-aparts · 5 inchworms\nThen (6 min): 10 goblet squats with a 3 s pause · 10 band side-steps each way · 10 empty-bar back squats"]}, {"kind": "strength", "label": "Strength", "title": "Back squat 4 × 8", "minutes": 20, "lift": {"movement": "Back squat", "gentleMovement": "Goblet squat", "mode": "percent", "sets": 4, "reps": 8, "pct": [null, 65, 65, 65], "note": "Ramp: bar × 10, 40% × 5, 50% × 3, 60% × 2. Rest 2:00. RPE 8 cap."}, "versions": ["Goblet box squat: 4 × 8, easy weight\nSit to a box at knee height. Same weight every set, leave 3–4 reps in the tank. Rest 2 min.", "Back squat: 4 × 8 @ 65%\nRest 2 min. If a set feels harder than 2 reps left, or form breaks, drop 5–10%.", "Back squat: 4 × 8 @ 65%\nRest 2 min. If a set feels harder than 2 reps left, or form breaks, drop 5–10%.", "Back squat: 4 × 8 @ 65%\nRest 2 min. If a set feels harder than 2 reps left, or form breaks, drop 5–10%."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Row/Swing EMOM", "minutes": 15, "versions": ["Every minute, 4 rounds (12 min):\nMin 1: 5/6 cal row · Min 2: 8 Russian kettlebell swings to chest height (13/18 lb) · Min 3: 4 incline step-back burpees, hands on a box\nNo rower free? 20 s step-jacks or marching.", "Every minute, 4 rounds (12 min):\nMin 1: 6/8 cal row · Min 2: 10 Russian kettlebell swings (18/26 lb) · Min 3: 5 step-back burpees\nNo rower free? 30 jumping jacks.", "Every minute, 4 rounds (12 min):\nMin 1: 8/10 cal row · Min 2: 12 kettlebell swings (26/35 lb) · Min 3: 6 burpees\nNo rower free? 70 single-unders.", "Every minute, 4 rounds (12 min):\nMin 1: 9/12 cal row · Min 2: 12 kettlebell swings (35/53 lb) · Min 3: 8 burpees\nNo rower free? 80 single-unders."]}, {"kind": "skill", "label": "Accessory", "title": "Lunges + hollow hold", "minutes": 5, "versions": ["3 rounds: 6 reverse lunges each side, holding the rig, short step · 20 s tuck hollow hold\nLeave 3–4 reps in the tank.", "3 rounds: 10 bodyweight reverse lunges each side · 30 s tuck hollow hold\nLeave 3 reps in the tank.", "3 rounds: 10 dumbbell reverse lunges each side · 30 s hollow hold\nLeave 3 reps in the tank.", "3 rounds: 10 dumbbell reverse lunges each side · 30 s hollow hold\nLeave 3 reps in the tank."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads.", "3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads.", "3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads.", "3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads."]}]'::jsonb, 'published', null)
