insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-27', 'Toes-to-Bar Test + Easy Rounds', 'Toes-to-bar · easy cardio', 'A first check on toes-to-bar, our skill for this block. Then steady, easy rounds on the bike and rower.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["400 m easy jog (or 500 m row) · leg swings · 2 × 20 m A-skips\nThen: 2 × (10 hollow rocks + 10 arch rocks) · 10 scap pull-ups · 2 × 100 m build-up strides", "400 m easy jog (or 500 m row) · leg swings · 2 × 20 m A-skips\nThen: 2 × (10 hollow rocks + 10 arch rocks) · 10 scap pull-ups · 2 × 100 m build-up strides", "400 m easy jog (or 500 m row) · leg swings · 2 × 20 m A-skips\nThen: 2 × (10 hollow rocks + 10 arch rocks) · 10 scap pull-ups · 2 × 100 m build-up strides", "400 m easy jog (or 500 m row) · leg swings · 2 × 20 m A-skips\nThen: 2 × (10 hollow rocks + 10 arch rocks) · 10 scap pull-ups · 2 × 100 m build-up strides"]}, {"kind": "skill", "label": "Test", "title": "Toes-to-bar test", "minutes": 13, "versions": ["Test: max lying bent-knee raises, unbroken\nOne fresh try, low back pressed down. Then every 2 min × 4 (level 1): 15 s tuck hollow hold · 4 lying bent-knee raises · 5 ring rows on a high bar, 3 s down\nWrite down your max and your level.", "Test: max hanging knee raises to hip height, unbroken\nOne fresh try. Then every 2 min × 4 (level 1): 20 s tuck hollow hold · 3 hanging knee raises · 3–5 ring rows, feet forward, 3 s down\nWrite down your max and your level.", "Test: max hanging knee raises to hip height, unbroken\nOne fresh try. Then every 2 min × 4 (level 1): 20 s hollow hold · 3 hanging knee raises · 3–5 band-assisted strict pull-ups, 3 s down\nWrite down your max and your level.", "Test: max toes-to-bar, unbroken\nOne fresh try. Then every 2 min × 4 (level 1): 20 s hollow hold · 3 hanging knee raises · 3–5 strict pull-ups, 3 s down\nWrite down your max and your level."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Bike/Row Easy Rounds", "minutes": 28, "versions": ["4 rounds, not for time (28 min). Easy, talk-able pace:\n12/15 cal air bike · 200 m row · 8 wall balls (4/6 lb) to a low target · 30 s step-jacks\nNo bike or rower free? Bike: 55 s step-jacks. Row: 50 s.", "4 rounds, not for time (28 min). Easy, talk-able pace:\n16/20 cal air bike · 300 m row · 10 wall balls (6/10 lb) · 30 s single-unders\nNo bike or rower free? Bike: 70 jumping jacks. Row: 75.", "4 rounds, not for time (28 min). Easy, talk-able pace:\n20/25 cal air bike · 400 m row · 15 wall balls (6/10 lb) · 30 s double-under attempts\nNo bike or rower free? Bike: 180 single-unders. Row: 200.", "4 rounds, not for time (28 min). Easy, talk-able pace:\n24/30 cal air bike · 400 m row · 15 wall balls (10/14 lb) · 30 s double-unders\nNo bike or rower free? Bike: 220 single-unders. Row: 200."], "outdoor": {"title": "Run/Row Easy Rounds", "versions": ["4 rounds, not for time (28 min). Easy, talk-able pace:\n300 m walk/jog · 200 m row · 8 wall balls (4/6 lb) to a low target · 30 s step-jacks\nNo rower free? 150 m walk/jog.", "4 rounds, not for time (28 min). Easy, talk-able pace:\n400 m run/walk · 300 m row · 10 wall balls (6/10 lb) · 30 s single-unders\nNo rower free? 250 m run.", "4 rounds, not for time (28 min). Easy, talk-able pace:\n500 m run · 400 m row · 15 wall balls (6/10 lb) · 30 s double-under attempts\nNo rower free? 300 m run.", "4 rounds, not for time (28 min). Easy, talk-able pace:\n600 m run · 400 m row · 15 wall balls (10/14 lb) · 30 s double-unders\nNo rower free? 300 m run."]}}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["Walk 2 min · calf and hamstring stretch 1 min each side · lat stretch on the rig 1 min", "Walk 2 min · calf and hamstring stretch 1 min each side · lat stretch on the rig 1 min", "Walk 2 min · calf and hamstring stretch 1 min each side · lat stretch on the rig 1 min", "Walk 2 min · calf and hamstring stretch 1 min each side · lat stretch on the rig 1 min"]}]'::jsonb, 'published', null)
