insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-10-28', 'Deadlift + Station AMRAP', 'Deadlift · steady stations', 'Deadlift sets at a moderate weight, then 20 minutes on four stations. Keep the same pace from the first round to the last.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["2 rounds (5 min): 250 m easy row · 10 PVC good mornings · 10 bird dogs · 5 push-ups\nThen (6 min): 10 kettlebell deadlifts · 8 empty-bar Romanian deadlifts", "2 rounds (5 min): 250 m easy row · 10 PVC good mornings · 10 bird dogs · 5 push-ups\nThen (6 min): 10 kettlebell deadlifts · 8 empty-bar Romanian deadlifts", "2 rounds (5 min): 250 m easy row · 10 PVC good mornings · 10 bird dogs · 5 push-ups\nThen (6 min): 10 kettlebell deadlifts · 8 empty-bar Romanian deadlifts", "2 rounds (5 min): 250 m easy row · 10 PVC good mornings · 10 bird dogs · 5 push-ups\nThen (6 min): 10 kettlebell deadlifts · 8 empty-bar Romanian deadlifts"]}, {"kind": "strength", "label": "Strength", "title": "Deadlift 3 × 8", "minutes": 16, "lift": {"movement": "Deadlift", "gentleMovement": "Kettlebell deadlift", "mode": "percent", "sets": 3, "reps": 8, "pct": [null, 65, 65, 65], "note": "Ramp: 40% × 5, 50% × 3, 60% × 2. Rest 2:00. RPE 8 cap."}, "versions": ["Kettlebell deadlift: 3 × 8, easy weight\nOne light kettlebell between your feet (on a low step if the floor is too far). Leave 3–4 reps in the tank. Rest 2 min.", "Deadlift: 3 × 8 @ 65%\nReset every rep, no bouncing. Rest 2 min. If a set feels harder than 2 reps left, or form breaks, drop 5–10%.", "Deadlift: 3 × 8 @ 65%\nReset every rep, no bouncing. Rest 2 min. If a set feels harder than 2 reps left, or form breaks, drop 5–10%.", "Deadlift: 3 × 8 @ 65%\nReset every rep, no bouncing. Rest 2 min. If a set feels harder than 2 reps left, or form breaks, drop 5–10%."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Station AMRAP", "minutes": 22, "versions": ["As many rounds as you can in 20 min, about 7/10 effort: breathing hard but controlled.\n6/8 cal row · 8 wall balls (4/6 lb) to a low target · 20 m farmers carry (2 × 13/18 lb) · 8 step-ups to a low step (total)\nNo rower free? 30 s step-jacks.", "As many rounds as you can in 20 min, about 7/10 effort: breathing hard but controlled.\n8/10 cal row · 10 wall balls (6/10 lb) · 20 m farmers carry (2 × 18/26 lb) · 10 bodyweight lunges (total)\nNo rower free? 35 jumping jacks.", "As many rounds as you can in 20 min, about 7/10 effort: breathing hard but controlled.\n10/12 cal row · 10 wall balls (6/10 lb) · 20 m farmers carry (2 × 26/35 lb) · 10 sandbag lunges (22/33 lb, total)\nNo rower free? 90 single-unders.", "As many rounds as you can in 20 min, about 7/10 effort: breathing hard but controlled.\n10/12 cal row · 10 wall balls (10/14 lb) · 20 m farmers carry (2 × 35/53 lb) · 10 sandbag lunges (22/44 lb, total)\nNo rower free? 90 single-unders."]}, {"kind": "skill", "label": "Accessory", "title": "Rows + farmers hold", "minutes": 4, "versions": ["3 rounds: 8 chest-supported dumbbell rows on an incline bench · 20 s farmers hold (2 × 13/18 lb)\nLeave 3–4 reps in the tank.", "3 rounds: 10 light dumbbell bent-over rows · 30 s farmers hold (2 × 18/26 lb)\nLeave 2–3 reps in the tank.", "3 rounds: 10 dumbbell bent-over rows · 30 s heavy farmers hold (2 × 35/53 lb)\nLeave 2–3 reps in the tank.", "3 rounds: 10 dumbbell bent-over rows · 30 s heavy farmers hold (2 × 35/53 lb)\nLeave 2–3 reps in the tank."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 4, "versions": ["3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s", "3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s", "3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s", "3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s"]}]'::jsonb, 'published', null)
