insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-19', 'Easy Day: Strength + Row/Bike', 'Accessory strength · easy cardio', 'The easy day: strength work for joints and posture, then easy row and bike intervals. Nobody should breathe hard today.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 7, "versions": ["2 min easy row · 10 cat-cows · 10 couch-stretch rocks each side\nThen: 5 bodyweight step-ups each side · 10 scap pull-ups · 10 wall slides", "2 min easy row · 10 cat-cows · 10 couch-stretch rocks each side\nThen: 5 bodyweight step-ups each side · 10 scap pull-ups · 10 wall slides", "2 min easy row · 10 cat-cows · 10 couch-stretch rocks each side\nThen: 5 bodyweight step-ups each side · 10 scap pull-ups · 10 wall slides", "2 min easy row · 10 cat-cows · 10 couch-stretch rocks each side\nThen: 5 bodyweight step-ups each side · 10 scap pull-ups · 10 wall slides"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory strength + core", "minutes": 21, "versions": ["Strength circuit: 3 rounds\n6 step-ups each side (low step, hold the rig) · 8 ring rows (high bar, body nearly upright) · 15 s side plank each side from the knees · 10 seated tibialis raises\nRest 1 min after each round. Leave 3–4 reps in the tank.", "Strength circuit: 3 rounds\n8 bodyweight step-ups each side (low box) · 10 ring rows, body more upright · 20 s side plank each side from the knees · 15 tibialis raises\nRest 1 min after each round. Leave 2–3 reps in the tank.", "Strength circuit: 3 rounds\n8 dumbbell step-ups each side (knee-height box) · 10 ring rows · 20 s short-lever Copenhagen plank each side · 15 tibialis raises\nRest 1 min after each round. Leave 2–3 reps in the tank.", "Strength circuit: 3 rounds\n8 dumbbell step-ups each side (knee-height box) · 10 ring rows · 20 s short-lever Copenhagen plank each side · 15 tibialis raises\nRest 1 min after each round. Leave 2–3 reps in the tank."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Easy row/bike intervals", "minutes": 21, "versions": ["2 rounds: 9 min easy, 1 min rest (19 min). Switch between row and air bike.\nVery easy: full sentences the whole time. Rounds can be 1–2 min shorter; slow pedalling is fine.\nNo machine free? Easy 1 min each: marching · low step-ups · wall push-ups. Repeat.", "2 rounds: 9 min easy, 1 min rest (19 min). Switch between row and air bike.\nEasy and chatty. Rounds can be 1 min shorter.\nNo machine free? Easy 1 min each: step-ups to a low box · jumping jacks · air squats. Repeat.", "2 rounds: 9 min easy, 1 min rest (19 min). Switch between row and air bike.\nEasy to steady, still able to talk in full sentences.\nNo machine free? Easy 1 min each: step-ups · jumping jacks · air squats · easy single-unders. Repeat.", "2 rounds: 9 min easy, 1 min rest (19 min). Switch between row and air bike.\nSteady, still able to talk in full sentences.\nNo machine free? Easy 1 min each: step-ups · jumping jacks · air squats · easy single-unders. Repeat."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + mobility", "minutes": 8, "versions": ["3 min easy row · pigeon stretch 1 min each side · shoulder stretch on a bench 1 min · dead hang 1 min", "3 min easy row · pigeon stretch 1 min each side · shoulder stretch on a bench 1 min · dead hang 1 min", "3 min easy row · pigeon stretch 1 min each side · shoulder stretch on a bench 1 min · dead hang 1 min", "3 min easy row · pigeon stretch 1 min each side · shoulder stretch on a bench 1 min · dead hang 1 min"]}]'::jsonb, 'published', null)
