insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-20', 'Clean + Press + 3 Rounds', 'Clean · press · short workout', 'Heavier power cleans and press sets of 3, then a short, fast workout with a light-to-moderate dumbbell.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["300 m easy row · 10 scap push-ups · 10 air squats\nThen, empty bar: clean pull from knee × 5 · high-hang power clean × 5 · front squat × 5 · 2 × 8 band presses", "300 m easy row · 10 scap push-ups · 10 air squats\nThen, empty bar: clean pull from knee × 5 · high-hang power clean × 5 · front squat × 5 · 2 × 8 band presses", "300 m easy row · 10 scap push-ups · 10 air squats\nThen, empty bar: clean pull from knee × 5 · high-hang power clean × 5 · front squat × 5 · 2 × 8 band presses", "300 m easy row · 10 scap push-ups · 10 air squats\nThen, empty bar: clean pull from knee × 5 · high-hang power clean × 5 · front squat × 5 · 2 × 8 band presses"]}, {"kind": "strength", "label": "Strength", "title": "Power clean technique", "minutes": 8, "versions": ["Dumbbell hang clean: every 2 min, same clock\nOne light dumbbell or kettlebell to your shoulder, then 1–2 goblet squats. Half the reps is fine; smooth reps only.", "Power clean: every 2 min × 6, 2 reps\nStay light: empty bar or light plates. Start from above the knee if the floor feels rushed. Fast, crisp reps.", "Power clean: every 2 min × 6, 2 reps\nBuild by feel, no percentages today. Fast, crisp reps; stop adding weight when they slow down.", "Power clean: every 2 min × 6, 2 reps\nBuild by feel, no percentages today. Fast, crisp reps; stop adding weight when they slow down."]}, {"kind": "strength", "label": "Strength", "title": "Strict press 5×3 @ 77.5%", "minutes": 10, "lift": {"movement": "Strict press", "gentleMovement": "Dumbbell press", "mode": "percent", "sets": 5, "reps": 3, "pct": [null, 77.5, 77.5, 77.5], "note": "Build in 2–3 lighter sets. Rest 1:30–2:00."}, "versions": ["Seated dumbbell press: 5 × 3, easy weight\nBack against a bench. Same weight every set, 3–4 reps in the tank. Rest 1:30–2:00. Between sets: 10 light rear-delt flys.", "Strict press: 5 × 3 @ 77.5%\nRest 1:30–2:00. Between sets: 10 light dumbbell rear-delt flys. If a set feels harder than 2 reps left, drop 5–10%.", "Strict press: 5 × 3 @ 77.5%\nRest 1:30–2:00. Between sets: 10 light dumbbell rear-delt flys. If a set feels harder than 2 reps left, drop 5–10%.", "Strict press: 5 × 3 @ 77.5%\nRest 1:30–2:00. Between sets: 10 light dumbbell rear-delt flys. If a set feels harder than 2 reps left, drop 5–10%."]}, {"kind": "conditioning", "label": "Conditioning", "title": "3 Rounds Row/Snatch/Burpee", "minutes": 19, "versions": ["3 rounds for time (12 min cap), rest when you need to:\n150 m row · 8 alternating dumbbell hang snatches (10/15 lb) · 6 incline step-back burpees (hands on a box)\nNo rower free? 40 s step-jacks or marching.", "3 rounds for time (12 min cap):\n200 m row · 12 alternating dumbbell snatches (15/20 lb) · 9 step-back burpees\nNo rower free? 50 jumping jacks.", "3 rounds for time (12 min cap):\n250 m row · 12 alternating dumbbell snatches (25/35 lb) · 9 bar-facing burpees\nNo rower free? 120 single-unders.", "3 rounds for time (12 min cap):\n250 m row · 12 alternating dumbbell snatches (35/50 lb) · 9 bar-facing burpees\nNo rower free? 120 single-unders."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 8, "versions": ["3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min", "3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min", "3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min", "3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min"]}]'::jsonb, 'published', null)
