insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-24', 'Toes-to-Bar + Row/Bike Rounds', 'Toes-to-bar · steady rounds', 'Keep your toes-to-bar clean while you''re breathing hard, then steady rounds at a pace you can talk at.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["2 min easy jump rope · 200 m jog · high knees and butt kicks\n10 scap pull-ups · 2 × 10 hollow-to-arch swings on the bar · 5 kipping knee raises · 2 × 100 m strides", "2 min easy jump rope · 200 m jog · high knees and butt kicks\n10 scap pull-ups · 2 × 10 hollow-to-arch swings on the bar · 5 kipping knee raises · 2 × 100 m strides", "2 min easy jump rope · 200 m jog · high knees and butt kicks\n10 scap pull-ups · 2 × 10 hollow-to-arch swings on the bar · 5 kipping knee raises · 2 × 100 m strides", "2 min easy jump rope · 200 m jog · high knees and butt kicks\n10 scap pull-ups · 2 × 10 hollow-to-arch swings on the bar · 5 kipping knee raises · 2 × 100 m strides"]}, {"kind": "skill", "label": "Skill", "title": "Toes-to-bar EMOM", "minutes": 13, "versions": ["Toes-to-bar level 5: every minute for 8 min\nOdd minutes: 30 s easy row or bike\nEven minutes: 6 lying bent-knee raises", "Toes-to-bar level 5: every minute for 8 min\nOdd minutes: 30 s easy row or bike\nEven minutes: 6 hanging knee raises", "Toes-to-bar level 5: every minute for 8 min\nOdd minutes: 30 s easy row or bike\nEven minutes: kipping knee raises + toes-to-bar singles", "Toes-to-bar level 5: every minute for 8 min\nOdd minutes: 30 s easy row or bike\nEven minutes: 4–6 toes-to-bar unbroken"]}, {"kind": "conditioning", "label": "Conditioning", "title": "Row/Bike Rounds", "minutes": 28, "versions": ["3 rounds, not for time (about 28 min), talk-able pace:\n250 m row · 6/8 cal row · 10 crunches · 5/6 cal air bike\nNo machine free? Step-jacks or marching: 1 min, 30 s, 20 s.", "3 rounds, not for time (about 28 min), talk-able pace:\n400 m row · 12/1