insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-25', 'Deadlift + Station Doubles', 'Deadlift · bike + stations', 'The heaviest deadlift sets of the block, then a short bike and two stations back to back, four times. The toughest mixed workout so far.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["3 min easy row, then 2 rounds: 10 banded hip hinges · 10 dead bugs each side · 10 ring rows\n5 slow RDLs · 3 deadlifts at 40–50% · ramp sets", "3 min easy row, then 2 rounds: 10 banded hip hinges · 10 dead bugs each side · 10 ring rows\n5 slow RDLs · 3 deadlifts at 40–50% · ramp sets", "3 min easy row, then 2 rounds: 10 banded hip hinges · 10 dead bugs each side · 10 ring rows\n5 slow RDLs · 3 deadlifts at 40–50% · ramp sets", "3 min easy row, then 2 rounds: 10 banded hip hinges · 10 dead bugs each side · 10 ring rows\n5 slow RDLs · 3 deadlifts at 40–50% · ramp sets"]}, {"kind": "strength", "label": "Strength", "title": "Deadlift 1 × 3 @ 80%", "minutes": 5, "lift": {"movement": "Deadlift", "gentleMovement": "Kettlebell deadlift", "mode": "percent", "sets": 1, "reps": 3, "pct": [null, 80, 80, 80], "note": "Ramp: 40% × 5, 50% × 3, 60% × 2. Reset every rep. RPE 8 cap."}, "versions": ["Kettlebell deadlift: 1 × 3, easy weight\nOne light kettlebell between your feet (on a low step if the floor is far). Leave 3–4 reps in the tank. Rest 2:30–3 min.", "Deadlift: 1 × 3 @ 80%\nA lighter set before the top sets. Rest 2:30–3 min. If a set feels harder than 2 reps left, drop 5–10%.", "Deadlift: 1 × 3 @ 80%\nA lighter set before the top sets. Rest 2:30–3 min. If a set feels harder than 2 reps left, drop 5–10%.", "Deadlift: 1 × 3 @ 80%\nA lighter set before the top sets. Rest 2:30–3 min. If a set feels harder than 2 reps left, drop 5–10%."]}, {"kind": "strength", "label": "Strength", "title": "Deadlift 2 × 3 @ 85%", "minutes": 11, "lift": {"movement": "Deadlift", "gentleMovement": "Kettlebell deadlift", "mode": "percent", "sets": 2, "reps": 3, "pct": [null, 85, 85, 85], "note": "Ramp: 40% × 5, 50% × 3, 60% × 2. Reset every rep. RPE 8 cap."}, "versions": ["Kettlebell deadlift: 2 × 3, easy weight\nOne light kettlebell between your feet (on a low step if the floor is far). Leave 3–4 reps in the tank. Rest 2:30–3 min.", "Deadlift: 2 × 3 @ 85%\nTop sets, after the ramp set. Rest 2:30–3 min. If a set feels harder than 2 reps left, drop 5–10%.", "Deadlift: 2 × 3 @ 85%\nTop sets, after the ramp set. Rest 2:30–3 min. If a set feels harder than 2 reps left, drop 5–10%.", "Deadlift: 2 × 3 @ 85%\nTop sets, after the ramp set. Rest 2:30–3 min. If a set feels harder than 2 reps left, drop 5–10%."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Bike + Station Doubles", "minutes": 24, "versions": ["4 rounds: 5/6 cal bike, then 2 stations:\nR1: 25 m sled push + 10 wall balls 4/6 lb, low target\nR2: 150 m row + 4 incline step-back burpees\nR3: 50 m farmer carry 2 × 13/18 lb + 10 low step-ups\nR4: 25 m sled pull + same wall balls\nSled: empty or 1 light plate.\nNo machine? Step-jacks: row 40 s, bike 20 s.", "4 rounds: 6/8 cal bike, then 2 stations:\nR1: 25 m sled push + 15 wall balls 6/10 lb\nR2: 200 m row + 6 step-back burpee broad jumps\nR3: 50 m farmer carry 2 × 18/26 lb + 16 lunges (13/22 lb sandbag optional)\nR4: 25 m sled pull + same wall balls\nSled: light plates.\nNo machine? Jumping jacks: row 50, bike 30.", "4 rounds: 8/10 cal bike, then 2 stations:\nR1: 25 m sled push + 20 wall balls 6/10 lb\nR2: 250 m row + 6 burpee broad jumps\nR3: 50 m farmer carry 2 × 26/35 lb + 16 sandbag lunges 22/33 lb\nR4: 25 m sled pull + same wall balls\nSled: about 25% lighter than Full.\nNo machine? Single-unders: row 120, bike 70.", "4 rounds: 8/10 cal bike, then 2 stations:\nR1: 25 m sled push + 20 wall balls 10/14 lb\nR2: 250 m row + 6 burpee broad jumps\nR3: 50 m farmer carry 2 × 35/53 lb + 16 sandbag lunges 22/44 lb\nR4: 25 m sled pull + same wall balls\nSled: heavy, but moving nonstop for 12.5 m.\nNo machine? Single-unders: row 120, bike 70."], "outdoor": {"title": "Run + Station Doubles", "versions": ["4 rounds: 100 m walk/jog, then 2 stations:\nR1: 25 m sled push + 10 wall balls 4/6 lb, low target\nR2: 150 m row + 4 incline step-back burpees\nR3: 50 m farmer carry 2 × 13/18 lb + 10 low step-ups\nR4: 25 m sled pull + same wall balls\nSled: empty or 1 light plate.\nNo rower? 100 m walk/jog.", "4 rounds: 150 m run/walk, then 2 stations:\nR1: 25 m sled push + 15 wall balls 6/10 lb\nR2: 200 m row + 6 step-back burpee broad jumps\nR3: 50 m farmer carry 2 × 18/26 lb + 16 lunges (13/22 lb sandbag optional)\nR4: 25 m sled pull + same wall balls\nSled: light plates.\nNo rower? 150 m run.", "4 rounds: 200 m run, then 2 stations:\nR1: 25 m sled push + 20 wall balls 6/10 lb\nR2: 250 m row + 6 burpee broad jumps\nR3: 50 m farmer carry 2 × 26/35 lb + 16 sandbag lunges 22/33 lb\nR4: 25 m sled pull + same wall balls\nSled: about 25% lighter than Full.\nNo rower? 200 m run.", "4 rounds: 200 m run, then 2 stations:\nR1: 25 m sled push + 20 wall balls 10/14 lb\nR2: 250 m row + 6 burpee broad jumps\nR3: 50 m farmer carry 2 × 35/53 lb + 16 sandbag lunges 22/44 lb\nR4: 25 m sled pull + same wall balls\nSled: heavy, but moving nonstop for 12.5 m.\nNo rower? 200 m run."]}}, {"kind": "skill", "label": "Accessory", "title": "Row + carry superset", "minutes": 3, "versions": ["2 rounds, leave 3–4 reps in the tank:\n6 ring rows on a high bar, body nearly upright · 15 m light sandbag bear-hug carry", "2 rounds, leave 2–3 reps in the tank:\n8 ring rows · 20 m light sandbag bear-hug carry", "2 rounds, leave 2–3 reps in the tank:\n6–8 feet-elevated ring rows · 20 m sandbag bear-hug carry", "2 rounds, leave 2–3 reps in the tank:\n6–8 strict chin-ups · 20 m sandbag bear-hug carry"]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 3, "versions": ["3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s", "3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s", "3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s", "3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s"]}]'::jsonb, 'published', null)
