insert into public.workout_coach_notes (class_date, body) values ('2026-11-25', 'Stagger the start: give each member a different starting round (R1–R4) so only 1–2 people share the sled. Swap in the sled substitutes when it''s busy.
No free sled: plate push on turf; pull → 2 × 10 heavy ring rows (Gentle: light plate push, 2 × 8 ring rows on a high bar).
Scaling: Masters (40+) never above 85%, RPE 8 is the ceiling. Newer lifters / first 4 weeks: same sets and reps with empty bar or light plates at RPE 7. Gentle: one easy weight every set at RPE 6–7 (3–4 reps left); fewer reps is fine. Pain: pain-free range, tell the coach. Warm-up for Gentle: step instead of jumping, walk instead of jogging.
Loads: e1RM × 0.8 (ramp) and × 0.85 (top sets), round to 5 lb. Ramp: 40% × 5, 50% × 3, 60% × 2; reset every rep, no bouncing; rest 2:30–3:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%).
Conditioning targets: Cap 24:00 · RPE Gentle 6, others 7 · Aim finish under the cap; Strong/Full last bike (or run) as fast as the first; Full 16:00–21:00 · Feel cardio / muscle · Pace sustain.
No machine (conditioning): Gentle 150 m row → 0:40, 5/6 cal bike → 0:20 step-jacks or marching. Steady 200 m row → 50 jumping jacks, bike → 30. Strong/Full 250 m row → 120 single-unders, bike → 70. Outside: row → 100 m walk/jog (Gentle), 150 m run (Steady), 200 m run (Strong/Full).
No machine (warm-up/cool-down): jumping jacks, marching or jump rope, ~1:00 per 250 m or 5 cal.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-26', 'Accessory + Easy Row/Bike', 'Accessory strength · easy intervals', 'The easy day: strength work for joints and posture, then easy intervals. Nobody should be breathing hard today.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 7, "versions": ["2 min easy row · 10 cat-cows · 10 couch-stretch rocks each side\n5 bodyweight step-ups each side · 10 scap pull-ups · 10 wall slides", "2 min easy row · 10 cat-cows · 10 couch-stretch rocks each side\n5 bodyweight step-ups each side · 10 scap pull-ups · 10 wall slides", "2 min easy row · 10 cat-cows · 10 couch-stretch rocks each side\n5 bodyweight step-ups each side · 10 scap pull-ups · 10 wall slides", "2 min easy row · 10 cat-cows · 10 couch-stretch rocks each side\n5 bodyweight step-ups each side · 10 scap pull-ups · 10 wall slides"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory strength + core", "minutes": 21, "versions": ["3 rounds, leave 3–4 reps in the tank, rest 1 min after each round:\n6 step-ups each side to a low step, holding the rig · 8 ring rows on a high bar, nearly upright\n15 s side plank from the knees each side · 10 seated tibialis raises", "3 rounds, leave 2–3 reps in the tank, rest 1 min after each round:\n8 bodyweight step-ups each side to a low box · 10 ring rows, body more upright\n20 s side plank from the knees each side · 15 tibialis raises", "3 rounds, leave 2–3 reps in the tank, rest 1 min after each round:\n8 dumbbell step-ups each side to a knee-height box · 10 ring rows\n20 s short-lever Copenhagen plank each side · 15 tibialis raises", "3 rounds, leave 2–3 reps in the tank, rest 1 min after each round:\n8 dumbbell step-ups each side to a knee-height box · 10 ring rows\n20 s short-lever Copenhagen plank each side · 15 tibialis raises"]}, {"kind": "conditioning", "label": "Conditioning", "title": "Easy Row/Bike Intervals", "minutes": 21, "versions": ["2 × 9 min easy, 1 min rest (19 min). Switch row and bike each round.\nVery easy: full sentences the whole time. Rounds can be 1–2 min shorter.\nNo machine free? Same clock, 1 min each: marching · low step-ups · wall push-ups.", "2 × 9 min easy, 1 min rest (19 min). Switch row and bike each round.\nEasy and chatty: full sentences the whole time. Rounds can be 1 min shorter.\nNo machine free? Same clock, 1 min each: step-ups to a low box · jumping jacks · air squats.", "2 × 9 min easy, 1 min rest (19 min). Switch row and bike each round.\nEasy: full sentences the whole time. Too breathless to talk? Slow down.\nNo machine free? Same clock, 1 min each: step-ups · jumping jacks · air squats · single-unders.", "2 × 9 min easy, 1 min rest (19 min). Switch row and bike each round.\nEasy: full sentences the whole time. Too breathless to talk? Slow down.\nNo machine free? Same clock, 1 min each: step-ups · jumping jacks · air squats · single-unders."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + mobility", "minutes": 8, "versions": ["3 min easy row · pigeon stretch 1 min each side · shoulder stretch on a bench 1 min · 1 min dead hang", "3 min easy row · pigeon stretch 1 min each side · shoulder stretch on a bench 1 min · 1 min dead hang", "3 min easy row · pigeon stretch 1 min each side · shoulder stretch on a bench 1 min · 1 min dead hang", "3 min easy row · pigeon stretch 1 min each side · shoulder stretch on a bench 1 min · 1 min dead hang"]}]'::jsonb, 'published', null)
