insert into public.workout_coach_notes (class_date, body) values ('2026-11-26', 'If there aren''t enough rowers and bikes, run the class in two waves: wave 1 does the intervals while wave 2 does the accessory strength, then swap at about minute 31; or send the overflow to the ''No machine free'' bodyweight rounds. The intervals have no outside version on purpose: Thursday is machine-only so weekly running volume stays as planned.
Warm-up for Gentle: step instead of jumping, walk instead of jogging, stay in a comfortable range.
Intervals: Cap 19:00 (fixed) · Effort RPE Gentle 3–4, Steady 4, Strong 4–5, Full 5 · Zone 2 · Aim same pace every round: row split 0:15–0:25 per 500 m slower than 1 km test split; bike same calories each round (±1); Gentle: you could keep going · Feel cardio (easy) · Pace sustain.
Masters or injury: today is the best day for extra mobility or rehab work.
No machine (warm-up/cool-down): jumping jacks, marching or jump rope, ~1:00 per 250 m or 5 cal.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-27', 'Clean + Press + 2 Rounds', 'Clean · press · short workout', 'Clean and front squat practice, the heaviest press sets of the block, then a short, fast finish.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["300 m easy row · 10 scap push-ups · 10 air squats\nclean pull from knee × 5 · high-hang power clean × 5 · front squat × 5 (empty bar) · 2 × 8 band presses", "300 m easy row · 10 scap push-ups · 10 air squats\nclean pull from knee × 5 · high-hang power clean × 5 · front squat × 5 (empty bar) · 2 × 8 band presses", "300 m easy row · 10 scap push-ups · 10 air squats\nclean pull from knee × 5 · high-hang power clean × 5 · front squat × 5 (empty bar) · 2 × 8 band presses", "300 m easy row · 10 scap push-ups · 10 air squats\nclean pull from knee × 5 · high-hang power clean × 5 · front squat × 5 (empty bar) · 2 × 8 band presses"]}, {"kind": "strength", "label": "Skill", "title": "Power clean technique", "minutes": 8, "versions": ["Dumbbell clean: every 2 min, 5 rounds\nOne light dumbbell or kettlebell: hang clean to your shoulder, then 1–2 goblet squats. Half the reps is fine. Easy, smooth reps.", "Power clean: every 2 min × 5\n1 power clean + 2 front squats. Stay light: empty bar or light plates; start from the hang if the floor feels rushed. Fast, crisp reps.", "Power clean: every 2 min × 5\n1 power clean + 2 front squats. Build by feel, no percentages. Stop adding weight when reps slow down.", "Power clean: every 2 min × 5\n1 power clean + 2 front squats. Build by feel, no percentages. Stop adding weight when reps slow down."]}, {"kind": "strength", "label": "Strength", "title": "Strict press 1 × 3 @ 80%", "minutes": 4, "lift": {"movement": "Strict press", "gentleMovement": "Dumbbell press", "mode": "percent", "sets": 1, "reps": 3, "pct": [null, 80, 80, 80], "note": "Build in 2–3 lighter sets. RPE 8 cap."}, "versions": ["Seated dumbbell press: 1 × 3, easy weight\nBack against a bench. Leave 3–4 reps in the tank. Rest 1:30–2 min, 10 light dumbbell rear-delt flys between sets.", "Strict press: 1 × 3 @ 80%\nA lighter set before the top sets. Rest 1:30–2 min, 10 light dumbbell rear-delt flys between sets. If a set feels harder than 2 reps left, drop 5–10%.", "Strict press: 1 × 3 @ 80%\nA lighter set before the top sets. Rest 1:30–2 min, 10 light dumbbell rear-delt flys between sets. If a set feels harder than 2 reps left, drop 5–10%.", "Strict press: 1 × 3 @ 80%\nA lighter set before the top sets. Rest 1:30–2 min, 10 light dumbbell rear-delt flys between sets. If a set feels harder than 2 reps left, drop 5–10%."]}, {"kind": "strength", "label": "Strength", "title": "Strict press 3 × 3 @ 82.5%", "minutes": 6, "lift": {"movement": "Strict press", "gentleMovement": "Dumbbell press", "mode": "percent", "sets": 3, "reps": 3, "pct": [null, 82.5, 82.5, 82.5], "note": "Build in 2–3 lighter sets. RPE 8 cap."}, "versions": ["Seated dumbbell press: 3 × 3, easy weight\nBack against a bench. Leave 3–4 reps in the tank. Rest 1:30–2 min, 10 light dumbbell rear-delt flys between sets.", "Strict press: 3 × 3 @ 82.5%\nTop sets, after the ramp set. Rest 1:30–2 min, 10 light dumbbell rear-delt flys between sets. If a set feels harder than 2 reps left, drop 5–10%.", "Strict press: 3 × 3 @ 82.5%\nTop sets, after the ramp set. Rest 1:30–2 min, 10 light dumbbell rear-delt flys between sets. If a set feels harder than 2 reps left, drop 5–10%.", "Strict press: 3 × 3 @ 82.5%\nTop sets, after the ramp set. Rest 1:30–2 min, 10 light dumbbell rear-delt flys between sets. If a set feels harder than 2 reps left, drop 5–10%."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Row/Swing/Thruster, 2 Rounds", "minutes": 19, "versions": ["2 rounds for time, 14 min cap:\n250 m row · 12 Russian kettlebell swings to chest height (13/18 lb) · 10 wall push-ups · 8 dumbbell thrusters (2 × 5 lb)\nNo rower free? 1 min step-jacks or marching.", "2 rounds for time, 14 min cap:\n400 m row · 20 kettlebell swings (18/26 lb) · 15 incline push-ups · 10 dumbbell thrusters (2 × 10 lb)\nNo rower free? 100 jumping jacks.", "2 rounds for time, 14 min cap:\n500 m row · 20 kettlebell swings (26/35 lb) · 15 push-ups · 10 dumbbell thrusters (2 × 15/20 lb)\nNo rower free? 250 single-unders.", "2 rounds for time, 14 min cap:\n500 m row · 20 kettlebell swings (35/53 lb) · 15 push-ups · 10 dumbbell thrusters (2 × 25/35 lb)\nNo rower free? 250 single-unders."], "outdoor": {"title": "Run/Swing/Thruster, 2 Rounds", "versions": ["2 rounds for time, 14 min cap:\n200 m walk/jog · 12 Russian kettlebell swings to chest height (13/18 lb) · 10 wall push-ups · 8 dumbbell thrusters (2 × 5 lb)", "2 rounds for time, 14 min cap:\n300 m run · 20 kettlebell swings (18/26 lb) · 15 incline push-ups · 10 dumbbell thrusters (2 × 10 lb)", "2 rounds for time, 14 min cap:\n400 m run · 20 kettlebell swings (26/35 lb) · 15 push-ups · 10 dumbbell thrusters (2 × 15/20 lb)", "2 rounds for time, 14 min cap:\n400 m run · 20 kettlebell swings (35/53 lb) · 15 push-ups · 10 dumbbell thrusters (2 × 25/35 lb)"]}}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 8, "versions": ["3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min", "3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min", "3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min", "3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min"]}]'::jsonb, 'published', null)
