insert into public.workout_coach_notes (class_date, body) values ('2026-11-27', 'Power clean: Every 2:00 × 5, 1 power clean + 2 front squats, build to RPE 8 (Steady: RPE 6 is plenty, empty bar or light plates, hang start OK). Gentle: RPE 5–6, dumbbell hang clean + 1–2 goblet squats. Build by feel, no percentages today.
Scaling: Masters (40+) never above 85%, RPE 8 is the ceiling. Newer lifters / first 4 weeks: same sets and reps with empty bar or light plates at RPE 7. Gentle: one easy weight every set at RPE 6–7 (3–4 reps left); fewer reps is fine. Pain: pain-free range, tell the coach. Warm-up for Gentle: step instead of jumping, walk instead of jogging.
Loads: e1RM × 0.8 (ramp) and × 0.825 (top sets), round to 5 lb. Build to the working weight in 2–3 lighter sets; rest 1:30–2:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%).
Conditioning targets: Cap 14:00 · Aim finish under the cap; Full 9:00–11:00 · Feel cardio · Pace reach.
No machine (conditioning): Gentle 250 m row → 1:00 step-jacks or marching; Steady 400 m row → 100 jumping jacks; Strong/Full 500 m row → 250 single-unders.
No machine (warm-up/cool-down): jumping jacks, marching or jump rope, ~1:00 per 250 m or 5 cal.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-11-30', 'Squat Primer + Row Sprints', 'Squat · row sprints', 'Lighter week. Two easy triples and one heavy double let you feel heavy weight without the fatigue. Short row sprints keep you sharp.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["400 m easy row or bike · 10 spiderman lunges with reach · 10 PVC pass-throughs\n8 slow goblet squats (3 s down) · 3 squat jumps · then build up to your squat weight", "400 m easy row or bike · 10 spiderman lunges with reach · 10 PVC pass-throughs\n8 slow goblet squats (3 s down) · 3 squat jumps · then build up to your squat weight", "400 m easy row or bike · 10 spiderman lunges with reach · 10 PVC pass-throughs\n8 slow goblet squats (3 s down) · 3 squat jumps · then build up to your squat weight", "400 m easy row or bike · 10 spiderman lunges with reach · 10 PVC pass-throughs\n8 slow goblet squats (3 s down) · 3 squat jumps · then build up to your squat weight"]}, {"kind": "strength", "label": "Strength · ramp sets", "title": "Back squat 2 × 3 @ 75%", "minutes": 6, "lift": {"movement": "Back squat", "gentleMovement": "Goblet squat", "mode": "percent", "sets": 2, "reps": 3, "pct": [null, 75, 75, 75], "note": "Ramp and RPE rules: see coach notes."}, "versions": ["Goblet box squat: 2 × 3, easy weight\nSit to a box at knee height. Leave 3–4 reps in the tank. Same weight every set. Rest 2 min.", "Back squat: 2 × 3 @ 75%\nLight sets before the top set. Rest 2 min. If a set feels harder than 2 reps left, drop 5–10%.", "Back squat: 2 × 3 @ 75%\nLight sets before the top set. Rest 2 min. If a set feels harder than 2 reps left, drop 5–10%.", "Back squat: 2 × 3 @ 75%\nLight sets before the top set. Rest 2 min. If a set feels harder than 2 reps left, drop 5–10%."]}, {"kind": "strength", "label": "Strength · top set", "title": "Back squat 1 × 2 @ 85%", "minutes": 14, "lift": {"movement": "Back squat", "gentleMovement": "Goblet squat", "mode": "percent", "sets": 1, "reps": 2, "pct": [null, 85, 85, 85], "note": "Ramp and RPE rules: see coach notes."}, "versions": ["Goblet box squat: 1 × 2, easy weight\nSame weight as before. Leave 3–4 reps in the tank. Rest 2 min.", "Back squat: 1 × 2 @ 85%\nYour top set. Rest 2 min. If it feels harder than 2 reps left, drop 5–10%.", "Back squat: 1 × 2 @ 85%\nYour top set. Rest 2 min. If it feels harder than 2 reps left, drop 5–10%.", "Back squat: 1 × 2 @ 85%\nYour top set. Rest 2 min. If it feels harder than 2 reps left, drop 5–10%."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Row Sprints", "minutes": 15, "versions": ["4 rounds: 45 s row sprint, then 2 min 15 s easy (12 min)\nFairly hard; sprints can be 30 s. Score: total metres.\nNo rower free? Fast marching or step-jacks, walk the easy part.", "4 rounds: 45 s row sprint, then 2 min 15 s easy (12 min)\nHard effort. Score: total metres.\nNo rower free? Fast jumping jacks, walk the easy part.", "4 rounds: 45 s row sprint, then 2 min 15 s easy (12 min)\nVery hard effort. Score: total metres.\nNo rower free? Fast single-unders or high knees, walk the easy part.", "4 rounds: 45 s row sprint, then 2 min 15 s easy (12 min)\nAll-out effort. Score: total metres.\nNo rower free? Max single-unders or high knees, walk the easy part."]}, {"kind": "skill", "label": "Accessory", "title": "Split squat + side plank", "minutes": 5, "versions": ["2 rounds: 6 split squats each side, holding the rig, short range · 15 s side plank each side, from the knees\nLeave 3–4 reps in the tank.", "2 rounds: 8 bodyweight split squats each side, holding the rig · 20 s side plank each side, from the knees\nLeave 3 reps in the tank.", "2 rounds: 8 split squats each side · 20 s side plank each side\nLeave 3 reps in the tank.", "2 rounds: 8 split squats each side · 20 s side plank each side\nLeave 3 reps in the tank."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads.", "3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads.", "3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads.", "3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads."]}]'::jsonb, 'published', null)
