insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-01', 'Toes-to-Bar + Easy Cardio', 'Toes-to-bar · easy cardio', 'Keep the toes-to-bar skill ticking over, then easy steady work. Leave fresher than you came in.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["400 m easy row or jog · 10 cat-cows · 10 PVC pass-throughs\n20 s hollow hold · 10 arch rocks · 2 × 5 kip swings · 2 × 3 easy toes-to-bar or knee raises", "400 m easy row or jog · 10 cat-cows · 10 PVC pass-throughs\n20 s hollow hold · 10 arch rocks · 2 × 5 kip swings · 2 × 3 easy toes-to-bar or knee raises", "400 m easy row or jog · 10 cat-cows · 10 PVC pass-throughs\n20 s hollow hold · 10 arch rocks · 2 × 5 kip swings · 2 × 3 easy toes-to-bar or knee raises", "400 m easy row or jog · 10 cat-cows · 10 PVC pass-throughs\n20 s hollow hold · 10 arch rocks · 2 × 5 kip swings · 2 × 3 easy toes-to-bar or knee raises"]}, {"kind": "skill", "label": "Skill", "title": "Toes-to-bar practice", "minutes": 13, "versions": ["Toes-to-bar practice: 3 sets over 8 min\n10 s tuck hollow hold + 3 lying bent-knee raises · rest 1:30\nNo fatigue: stop with reps in the tank.", "Toes-to-bar practice: 3 sets over 8 min\n3 hanging knee raises + 3 lying leg raises · rest 1:30\nNo fatigue: stop with reps in the tank.", "Toes-to-bar practice: 3 sets over 8 min\n3 kip swings + 3 kipping knee raises · rest 1:30\nNo fatigue: stop with reps in the tank.", "Toes-to-bar practice: 3 sets over 8 min\n3 kip swings + 3 toes-to-bar · rest 1:30\nNo fatigue: stop with reps in the tank."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Easy Bike/Row/Wall Ball", "minutes": 28, "versions": ["2 rounds, easy (22 min):\n12/15 cal air bike · 300 m row · 8 light wall balls (4/6 lb)\nTalk-able pace the whole time. No score.\nNo machines free? 1:15 step-jacks for the row, 0:55 for the bike.", "2 rounds, easy (22 min):\n16/20 cal air bike · 400 m row · 10 li