insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-02', 'Deadlift Primer + Stations', 'Deadlift · stations', 'Lighter week. Two easy triples and one heavy single, then two short blocks on stations at a hard but smooth pace.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["400 m easy row · 10 jumping jacks · 5 supported hip airplanes each side\n2 × 5 deadlifts, building · 5 kettlebell swings · then build up to your deadlift weight", "400 m easy row · 10 jumping jacks · 5 supported hip airplanes each side\n2 × 5 deadlifts, building · 5 kettlebell swings · then build up to your deadlift weight", "400 m easy row · 10 jumping jacks · 5 supported hip airplanes each side\n2 × 5 deadlifts, building · 5 kettlebell swings · then build up to your deadlift weight", "400 m easy row · 10 jumping jacks · 5 supported hip airplanes each side\n2 × 5 deadlifts, building · 5 kettlebell swings · then build up to your deadlift weight"]}, {"kind": "strength", "label": "Strength · ramp sets", "title": "Deadlift 2 × 3 @ 75%", "minutes": 5, "lift": {"movement": "Deadlift", "gentleMovement": "Kettlebell deadlift", "mode": "percent", "sets": 2, "reps": 3, "pct": [null, 75, 75, 75], "note": "Ramp and RPE rules: see coach notes."}, "versions": ["Kettlebell deadlift: 2 × 3, easy weight\nOne light kettlebell between your feet. Leave 3–4 reps in the tank. Rest 2 min.", "Deadlift: 2 × 3 @ 75%\nLight sets before the top set. Rest 2 min. If a set feels harder than 2 reps left, drop 5–10%.", "Deadlift: 2 × 3 @ 75%\nLight sets before the top set. Rest 2 min. If a set feels harder than 2 reps left, drop 5–10%.", "Deadlift: 2 × 3 @ 75%\nLight sets before the top set. Rest 2 min. If a set feels harder than 2 reps left, drop 5–10%."]}, {"kind": "strength", "label": "Strength · top set", "title": "Deadlift 1 × 1 @ 85%", "minutes": 11, "lift": {"movement": "Deadlift", "gentleMovement": "Kettlebell deadlift", "mode": "percent", "sets": 1, "reps": 1, "pct": [null, 85, 85, 85], "note": "Ramp and RPE rules: see coach notes."}, "versions": ["Kettlebell deadlift: 1 × 1, easy weight\nSame weight as before. Leave 3–4 reps in the tank. Rest 2 min.", "Deadlift: 1 × 1 @ 85%\nYour top single. Rest 2 min. If it feels harder than 2 reps left, drop 5–10%.", "Deadlift: 1 × 1 @ 85%\nYour top single. Rest 2 min. If it feels harder than 2 reps left, drop 5–10%.", "Deadlift: 1 × 1 @ 85%\nYour top single. Rest 2 min. If it feels harder than 2 reps left, drop 5–10%."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Station Blocks", "minutes": 22, "versions": ["2 × 8 min: as many rounds as you can, rest 2 min between\n5/6 cal row · 8 wall balls (4/6 lb) to a low target · 20 m farmers carry (2 × 13/18 lb)\nHard but smooth, about 7/10.\nNo rower free? 20 s step-jacks or marching.", "2 × 8 min: as many rounds as you can, rest 2 min between\n6/8 cal row · 10 wall balls (6/10 lb) · 20 m farmers carry (2 × 18/26 lb)\nHard but smooth, about 7/10.\nNo rower free? 30 jumping jacks.", "2 × 8 min: as many rounds as you can, rest 2 min between\n9/12 cal row · 10 wall balls (6/10 lb) · 20 m farmers carry (2 × 26/35 lb)\nHard but smooth, about 7/10.\nNo rower free? 80 single-unders.", "2 × 8 min: as many rounds as you can, rest 2 min between\n9/12 cal row · 10 wall balls (10/14 lb) · 20 m farmers carry (2 × 35/53 lb)\nHard but smooth, about 7/10.\nNo rower free? 80 single-unders."]}, {"kind": "skill", "label": "Accessory", "title": "Rows + suitcase carry", "minutes": 4, "versions": ["2 rounds: 8 light chest-supported dumbbell rows · 15 m light kettlebell suitcase carry each side\nLeave 3–4 reps in the tank.", "2 rounds: 10 light dumbbell rows · 20 m kettlebell suitcase carry each side\nLeave 3 reps in the tank.", "2 rounds: 10 dumbbell rows · 20 m heavy kettlebell suitcase carry each side\nLeave 3 reps in the tank.", "2 rounds: 10 dumbbell rows · 20 m heavy kettlebell suitcase carry each side\nLeave 3 reps in the tank."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 4, "versions": ["3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s", "3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s", "3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s", "3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s"]}]'::jsonb, 'published', null)
