insert into public.workout_coach_notes (class_date, body) values ('2026-12-02', 'Deload week. No running in this piece, so no outside version.
Scaling: Masters (40+) never above 85%, RPE 8 is the ceiling. Newer lifters / first 4 weeks: same sets and reps with empty bar or light plates at RPE 7. Pain: pain-free range, tell the coach. Gentle: KB deadlift (one light KB between the feet, on a low step if the floor is too far) at RPE 6–7; fewer reps fine if they slow. Gentle warm-up: step instead of jumping, walk instead of jogging, comfortable range.
Loads: e1RM × 0.75 (ramp sets) and × 0.85 (top single), round to 5 lb (lookup table in the coach book). Ramp: 40% × 5, 50% × 3, 60% × 2; reset every rep, no bouncing; rest 2:00. RPE 8 cap: past RPE 8 or form breaks, drop 5–10%; every set RPE 6 or easier, add 2.5–5% next week (max +5%).
Conditioning targets: threshold, about 7/10 (Gentle RPE 5–6, others RPE 6–7) · Cap 18:00 · Aim: Gentle steady, blocks don''t have to match; Steady block 2 = block 1; Strong/Full block 2 = block 1 (±1 round) · Feel cardio · Pace sustain.
No machine (conditioning): Gentle 5/6 cal row → 0:20 step-jacks or marching; Steady 6/8 cal → 30 jumping jacks; Strong/Full 9/12 cal → 80 single-unders.
No machine: warm-up/cool-down machine → easy jumping jacks, marching or jump rope, ~1:00 per 250 m or 5 cal.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-03', 'Accessories + Easy Intervals', 'Accessory strength · easy intervals', 'The easy day: strength work for joints and posture, then easy row and bike intervals. Nobody should breathe hard today.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 7, "versions": ["2 min easy bike · 10 deep-squat pries · 10 ankle rocks each side\n5 bodyweight split squats each side · 10 band face pulls · 20 s hollow hold", "2 min easy bike · 10 deep-squat pries · 10 ankle rocks each side\n5 bodyweight split squats each side · 10 band face pulls · 20 s hollow hold", "2 min easy bike · 10 deep-squat pries · 10 ankle rocks each side\n5 bodyweight split squats each side · 10 band face pulls · 20 s hollow hold", "2 min easy bike · 10 deep-squat pries · 10 ankle rocks each side\n5 bodyweight split squats each side · 10 band face pulls · 20 s hollow hold"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory strength + core", "minutes": 21, "versions": ["2 rounds, rest 1 min between · leave 3–4 reps in the tank\n8 split squats each side (hold the rig, short range) · 10 light rear-delt flys, chest on an incline bench · 20 s tuck hollow hold · 20 m light suitcase carry each side", "2 rounds, rest 1 min between · leave 3 reps in the tank\n10 bodyweight split squats each side (hold the rig if needed) · 12 light dumbbell rear-delt flys · 30 s tuck hollow hold · 30 m light suitcase carry each side", "2 rounds, rest 1 min between · leave 3 reps in the tank\n10 dumbbell split squats each side · 12 dumbbell rear-delt flys · 30 s hollow hold · 30 m suitcase carry each side", "2 rounds, rest 1 min between · leave 3 reps in the tank\n10 dumbbell split squats each side · 12 dumbbell rear-delt flys · 30 s hollow hold · 30 m suitcase carry each side"]}, {"kind": "conditioning", "label": "Conditioning", "title": "Easy row/bike intervals", "minutes": 21, "versions": ["3 rounds: 4 min very easy, 1 min rest (14 min)\nSwap row and air bike each round. Rounds can be 1–2 min shorter; slow pedalling is fine. Talk in full sentences.\nNo machine free? 1 min each: marching · step-ups to a low step · wall push-ups. Repeat.", "3 rounds: 4 min easy, 1 min rest (14 min)\nSwap row and air bike each round. Rounds can be 1 min shorter. Talk in full sentences.\nNo machine free? 1 min each: step-ups to a low box · jumping jacks · air squats. Repeat.", "3 rounds: 4 min easy, 1 min rest (14 min)\nSwap row and air bike each round. Talk in full sentences, same pace every round.\nNo machine free? 1 min each: step-ups · jumping jacks · air squats · easy single-unders. Repeat.", "3 rounds: 4 min easy, 1 min rest (14 min)\nSwap row and air bike each round. Talk in full sentences, same pace every round.\nNo machine free? 1 min each: step-ups · jumping jacks · air squats · easy single-unders. Repeat."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + mobility", "minutes": 8, "versions": ["3 min easy bike · couch stretch 1 min each side · adductor rocks · box breathing 1 min", "3 min easy bike · couch stretch 1 min each side · adductor rocks · box breathing 1 min", "3 min easy bike · couch stretch 1 min each side · adductor rocks · box breathing 1 min", "3 min easy bike · couch stretch 1 min each side · adductor rocks · box breathing 1 min"]}]'::jsonb, 'published', null)
