insert into public.workout_coach_notes (class_date, body) values ('2026-12-03', 'If there aren''t enough rowers and bikes, run the class in two waves: wave 1 does the intervals while wave 2 does the accessory strength, then swap at about minute 31; or send the overflow to the ''No machine free'' bodyweight rounds. The intervals have no outside version on purpose: Thursday is machine-only so weekly running volume stays as planned.
Scaling: Gentle warm-up: step instead of jumping, walk instead of jogging, comfortable range. Masters or injury: today is the best day for extra mobility or rehab work.
Conditioning targets: Effort Gentle RPE 3–4, Steady RPE 4, Strong RPE 4–5, Full RPE 5 (zone 2: full sentences; only a few words → slow down) · Cap 14:00 (fixed) · Aim: Gentle same easy pace every round, could keep going; Steady/Strong/Full same pace every round: row split 0:15–0:25 per 500 m slower than 1 km test split, bike same calories each round (±1) · Feel cardio (easy) · Pace sustain.
No machine: warm-up/cool-down machine → easy jumping jacks, marching or jump rope, ~1:00 per 250 m or 5 cal.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-04', 'Clean + Press + Short Sprint', 'Clean · press · short sprint', 'Fast and fresh: light power cleans, a few heavier presses, then a quick sprint to sharpen up.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["2 min jump rope · 5 inchworm push-ups · 10 lunges\n7 min, empty bar: 5 hang power cleans · 5 push presses · 5 push jerks · then build up to your press weight", "2 min jump rope · 5 inchworm push-ups · 10 lunges\n7 min, empty bar: 5 hang power cleans · 5 push presses · 5 push jerks · then build up to your press weight", "2 min jump rope · 5 inchworm push-ups · 10 lunges\n7 min, empty bar: 5 hang power cleans · 5 push presses · 5 push jerks · then build up to your press weight", "2 min jump rope · 5 inchworm push-ups · 10 lunges\n7 min, empty bar: 5 hang power cleans · 5 push presses · 5 push jerks · then build up to your press weight"]}, {"kind": "strength", "label": "Skill", "title": "Power clean EMOM", "minutes": 8, "versions": ["Dumbbell clean: every minute for 6 min\nHang clean a light dumbbell or kettlebell to your shoulder, then 1–2 goblet squats. Half the reps is fine; smooth reps only.", "Power clean: every minute for 6 min, 2 reps\nLight and fast: empty bar or light plates. Start from above the knee if the floor feels rushed.", "Power clean: every minute for 6 min, 2 reps\nLight and fast. Build by feel; stop adding weight when the bar slows down.", "Power clean: every minute for 6 min, 2 reps\nLight and fast. Build by feel; stop adding weight when the bar slows down."]}, {"kind": "strength", "label": "Strength · ramp sets", "title": "Strict press 2 × 3 @ 75%", "minutes": 4, "lift": {"movement": "Strict press", "gentleMovement": "Dumbbell press", "mode": "percent", "sets": 2, "reps": 3, "pct": [null, 75, 75, 75], "note": "Ramp and RPE rules: see coach notes."}, "versions": ["Seated dumbbell press: 2 × 3, easy weight\nBack against a bench. Leave 3–4 reps in the tank. Rest 1:30–2 min; 10 light rear-delt flys between sets.", "Strict press: 2 × 3 @ 75%\nLight sets before the top set. Rest 1:30–2 min; 10 light dumbbell rear-delt flys between sets. If a set feels harder than 2 reps left, drop 5–10%.", "Strict press: 2 × 3 @ 75%\nLight sets before the top set. Rest 1:30–2 min; 10 light dumbbell rear-delt flys between sets. If a set feels harder than 2 reps left, drop 5–10%.", "Strict press: 2 × 3 @ 75%\nLight sets before the top set. Rest 1:30–2 min; 10 light dumbbell rear-delt flys between sets. If a set feels harder than 2 reps left, drop 5–10%."]}, {"kind": "strength", "label": "Strength · top set", "title": "Strict press 1 × 2 @ 82.5%", "minutes": 6, "lift": {"movement": "Strict press", "gentleMovement": "Dumbbell press", "mode": "percent", "sets": 1, "reps": 2, "pct": [null, 82.5, 82.5, 82.5], "note": "Ramp and RPE rules: see coach notes."}, "versions": ["Seated dumbbell press: 1 × 2, easy weight\nSame weight as before. Leave 3–4 reps in the tank. Rest 1:30–2 min; 10 light rear-delt flys between sets.", "Strict press: 1 × 2 @ 82.5%\nYour top set. Rest 1:30–2 min; 10 light dumbbell rear-delt flys between sets. If it feels harder than 2 reps left, drop 5–10%.", "Strict press: 1 × 2 @ 82.5%\nYour top set. Rest 1:30–2 min; 10 light dumbbell rear-delt flys between sets. If it feels harder than 2 reps left, drop 5–10%.", "Strict press: 1 × 2 @ 82.5%\nYour top set. Rest 1:30–2 min; 10 light dumbbell rear-delt flys between sets. If it feels harder than 2 reps left, drop 5–10%."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Bike/Core/Wall Ball Sprint", "minutes": 19, "versions": ["2 rounds for time (10 min cap):\n5/6 cal air bike · 8 lying bent-knee raises · 10 wall balls (4/6 lb) to a low target\nNo bike free? 20 s step-jacks or marching.", "2 rounds for time (10 min cap):\n8/10 cal air bike · 12 lying leg raises · 15 wall balls (6/10 lb)\nNo bike free? 35 jumping jacks.", "2 rounds for time (10 min cap):\n12/15 cal air bike · 12 hanging knee raises · 15 wall balls (10/14 lb)\nNo bike free? 110 single-unders.", "2 rounds for time (10 min cap):\n12/15 cal air bike · 12 toes-to-bar · 15 wall balls (14/20 lb)\nNo bike free? 110 single-unders."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 8, "versions": ["3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min", "3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min", "3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min", "3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min"]}]'::jsonb, 'published', null)
