insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-07', 'Squat Test + Bike Intervals', 'Squat test · bike intervals', 'Same squat test as Week 1, so you can see how far you''ve come. Then short, fast bike intervals to open up the lungs.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["400 m easy row or bike · 10 spiderman lunges with reach · 10 PVC pass-throughs\n8 slow goblet squats (3 s down) · 3 squat jumps · then build-up sets", "400 m easy row or bike · 10 spiderman lunges with reach · 10 PVC pass-throughs\n8 slow goblet squats (3 s down) · 3 squat jumps · then build-up sets", "400 m easy row or bike · 10 spiderman lunges with reach · 10 PVC pass-throughs\n8 slow goblet squats (3 s down) · 3 squat jumps · then build-up sets", "400 m easy row or bike · 10 spiderman lunges with reach · 10 PVC pass-throughs\n8 slow goblet squats (3 s down) · 3 squat jumps · then build-up sets"]}, {"kind": "strength", "label": "Test", "title": "Back squat test: heavy 3", "minutes": 20, "lift": {"movement": "Back squat", "gentleMovement": "Goblet squat", "mode": "build", "sets": 1, "reps": 3, "pct": [null, null, null, null], "note": "No grinders. Week 1 3RM × 1.06 = e1RM this block."}, "versions": ["Goblet squat test: build to a heavy set of 3\nLight × 8, then 3 sets of 3, then 2–4 tries at 3. Stop at RPE 8 (2 reps left). 18 min.\nWrite down your weight and the change from Week 1.", "Back squat test: build to a heavy set of 3\nEmpty bar × 8, then build in 3s, then 2–4 tries at 3, adding 5–10 lb each time. Stop when form slips. 18 min.\nWrite down your weight and the change from Week 1.", "Back squat test: build to a heavy set of 3\nEmpty bar × 8, then build in 3s, then 2–4 tries at 3, adding 5–15 lb each time. Stop when form slips. 18 min.\nWrite down your weight and the change from Week 1.", "Back squat test: build to a heavy set of 3\nEmpty bar × 8, then build in 3s, then 2–4 tries at 3, adding 5–20 lb each time. Stop when form slips. 18 min.\nWrite down your weight and the change from Week 1."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Bike intervals", "minutes": 13, "versions": ["6 rounds: 0:30 hard / 1:30 easy (12 min)\nAir bike or rower, whichever feels easier; same machine as Week 1. Smooth, not all-out. Hard pieces can be 0:20.\nNo machine free? Fast marching or step-jacks, then a slow walk.", "6 rounds: 0:30 hard / 1:30 easy (12 min)\nAir bike or rower; same machine as Week 1. Hard but smooth. Try to beat your Week 1 calories.\nNo machine free? Jumping jacks, then walk.", "6 rounds: 0:30 hard / 1:30 easy (12 min)\nRower; same machine as Week 1. Hard. Try to beat your Week 1 calories.\nNo rower free? Fast single-unders or high knees, then walk.", "6 rounds: 0:30 hard / 1:30 easy (12 min)\nAir bike; same machine as Week 1. All-out on the hard pieces. Try to beat your Week 1 calories.\nNo bike free? Max-effort single-unders or high knees, then walk."]}, {"kind": "skill", "label": "Accessory", "title": "Split squat + side plank", "minutes": 5, "versions": ["2 rounds: 6 split squats each side, holding the rig, short range · 15 s side plank from the knees each side\nLeave 3–4 reps in the tank.", "2 rounds: 10 bodyweight split squats each side (hold the rig if needed) · 30 s side plank from the knees each side\nLeave 3 reps in the tank.", "2 rounds: 10 light dumbbell split squats each side · 30 s side plank each side\nLeave 3 reps in the tank.", "2 rounds: 10 light dumbbell split squats each side · 30 s side plank each side\nLeave 3 reps in the tank."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + log", "minutes": 7, "versions": ["3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads and write your best set of 3 on your scorecard.", "3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads and write your best set of 3 on your scorecard.", "3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads and write your best set of 3 on your scorecard.", "3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads and write your best set of 3 on your scorecard."]}]'::jsonb, 'published', null)
