insert into public.workout_coach_notes (class_date, body) values ('2026-12-07', 'Two coaches on test days if possible. Watch depth and back position; you call the set. Steady, Strong and Full test the barbell back squat (smaller jumps at Steady); only Gentle tests the goblet squat (bell at chest, sit to a box for a depth guide if needed). Machine-only intervals: Monday has no running on purpose (heavy-leg day), so no outside version.
Test: 3RM in 18 min. Barbell ladder: bar × 8, ~50% × 5, ~65% × 3, ~75% × 3, then 2–4 attempts at 3. Gentle: light × 8, 3 sets of 3, then 2–4 attempts, stop at RPE 8. No RPE 9–10 grinders. Use Week 1 result as the second-to-last attempt. Record 3RM in lb, level, change from Week 1. Week 1 3RM × 1.06 = e1RM for every squat % this block.
Scaling: Newer lifters / first 4 weeks after on-ramp: empty or training bar, no max attempt; stop at first RPE 8 set and record that. Masters (40+): RPE 8 max on the hard pieces. Knee or back pain: air bike only. Gentle warm-up: step instead of jumping, walk instead of jogging, comfortable range.
Conditioning targets: Cap 12:00 (fixed) · Aim: beat Week 1 average calories per hard piece · Feel: gas · Pace: reach. Hard = RPE 6 / 7 / 8 / 9 (Gentle to Full). No-machine score = reps instead of calories.
No machine: warm-up/cool-down machine → jumping jacks, marching or jump rope, ~1:00 per 250 m or 5 cal.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-08', '1 km Test + Toes-to-Bar', '1 km test · toes-to-bar', 'Same 1 km test as Week 1, so compare your time. Toes-to-bar stays light today.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["400 m easy row or jog · 10 cat-cows · 10 PVC pass-throughs\n20 s hollow hold · 10 arch rocks · 2 × 5 kip swings · 2 × 3 easy toes-to-bar or knee raises", "400 m easy row or jog · 10 cat-cows · 10 PVC pass-throughs\n20 s hollow hold · 10 arch rocks · 2 × 5 kip swings · 2 × 3 easy toes-to-bar or knee raises", "400 m easy row or jog · 10 cat-cows · 10 PVC pass-throughs\n20 s hollow hold · 10 arch rocks · 2 × 5 kip swings · 2 × 3 easy toes-to-bar or knee raises", "400 m easy row or jog · 10 cat-cows · 10 PVC pass-throughs\n20 s hollow hold · 10 arch rocks · 2 × 5 kip swings · 2 × 3 easy toes-to-bar or knee raises"]}, {"kind": "skill", "label": "Skill", "title": "Toes-to-bar practice", "minutes": 13, "versions": ["Toes-to-bar practice: every 2 min × 4\n5 lying bent-knee raises · 10 s tuck hollow hold\nNot a test; the retest is Week 9.", "Toes-to-bar practice: every 2 min × 4\n5 hanging knee raises\nNot a test; the retest is Week 9.", "Toes-to-bar practice: every 2 min × 4\n2 kip swings · 3–5 kipping knee raises\nNot a test; the retest is Week 9.", "Toes-to-bar practice: every 2 min × 4\n2 kip swings · 3–5 toes-to-bar\nNot a test; the retest is Week 9."]}, {"kind": "conditioning", "label": "Test", "title": "1,000 m row test", "minutes": 15, "versions": ["1,000 m row, steady and comfortable-hard. A short pause at 500 m is fine (note it).\nSame rower as Week 1. Walk 8–10 min after.\nWrite down your time, level, and whether you ran or rowed.\nNo rower free? Take the next one, or run 1 km outside.", "1,000 m row, as fast as you can hold the whole way.\nSame rower as Week 1. Walk 8–10 min after.\nWrite down your time, level, and whether you ran or 