insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-09', 'Deadlift Test + Easy Bike', 'Deadlift test · easy bike', 'Deadlift retest, so compare with Week 1. Then an easy bike workout to move and breathe: no hinging, nothing like yesterday.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["400 m easy row · 10 jumping jacks · 5 supported hip airplanes each side\n2 × 5 deadlifts, building · 5 kettlebell swings · then build-up sets", "400 m easy row · 10 jumping jacks · 5 supported hip airplanes each side\n2 × 5 deadlifts, building · 5 kettlebell swings · then build-up sets", "400 m easy row · 10 jumping jacks · 5 supported hip airplanes each side\n2 × 5 deadlifts, building · 5 kettlebell swings · then build-up sets", "400 m easy row · 10 jumping jacks · 5 supported hip airplanes each side\n2 × 5 deadlifts, building · 5 kettlebell swings · then build-up sets"]}, {"kind": "strength", "label": "Test", "title": "Deadlift test: heavy 3", "minutes": 18, "lift": {"movement": "Deadlift", "gentleMovement": "Kettlebell deadlift", "mode": "build", "sets": 1, "reps": 3, "pct": [null, null, null, null], "note": "Reset every rep. Week 1 3RM × 1.06 = e1RM this block."}, "versions": ["Kettlebell deadlift test: build to a heavy set of 3\nLight × 5, then 3 sets of 3, then 2–4 tries at 3. Reset each rep. Stop at RPE 8 (2 reps left). 16 min.\nWrite down your weight and the change from Week 1.", "Deadlift test: build to a heavy set of 3\nLight × 5, then build in 3s, then 2–4 tries at 3, adding 5–15 lb each time. Reset each rep. 16 min.\nWrite down your weight and the change from Week 1.", "Deadlift test: build to a heavy set of 3\nLight × 5, then build in 3s, then 2–4 tries at 3, adding 10–20 lb each time. Reset each rep. 16 min.\nWrite down your weight and the change from Week 1.", "Deadlift test: build to a heavy set of 3\nLight × 5, then build in 3s, then 2–4 tries at 3, adding 10–30 lb each time. Reset each rep. 16 min.\nWrite down your weight and the change from Week 1."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Easy bike EMOM", "minutes": 14, "versions": ["Every minute for 12 min (3 rounds), easy, not for score:\nMin 1 and 3: 0:30 very easy air bike · Min 2: 6 reverse lunges each side, holding the rig · Min 4: 10 m hands-and-knees crawl + 8 glute bridges\nNo bike free? 0:30 step-jacks or marching.", "Every minute for 12 min (3 rounds), easy, not for score:\nMin 1 and 3: 0:40 easy air bike · Min 2: 8 reverse lunges each side · Min 4: 15 m bear crawl + 10 glute bridges\nNo bike free? 0:40 easy jumping jacks.", "Every minute for 12 min (3 rounds), easy, not for score:\nMin 1 and 3: 0:40 easy air bike · Min 2: 8 reverse lunges each side · Min 4: 20 m bear crawl + 10 glute bridges\nNo bike free? 0:40 easy single-unders.", "Every minute for 12 min (3 rounds), easy, not for score:\nMin 1 and 3: 0:40 easy air bike · Min 2: 10 reverse lunges each side · Min 4: 20 m bear crawl + 12 glute bridges\nNo bike free? 0:40 easy single-unders."], "outdoor": {"title": "Easy jog EMOM", "versions": ["Every minute for 12 min (3 rounds), easy, not for score:\nMin 1 and 3: 100 m walk/jog, walk the rest · Min 2: 6 reverse lunges each side, holding the rig · Min 4: 10 m hands-and-knees crawl + 8 glute bridges", "Every minute for 12 min (3 rounds), easy, not for score:\nMin 1 and 3: 100 m easy jog/walk, walk the rest · Min 2: 8 reverse lunges each side · Min 4: 15 m bear crawl + 10 glute bridges", "Every minute for 12 min (3 rounds), easy, not for score:\nMin 1 and 3: 100 m easy jog, walk the rest · Min 2: 8 reverse lunges each side · Min 4: 20 m bear crawl + 10 glute bridges", "Every minute for 12 min (3 rounds), easy, not for score:\nMin 1 and 3: 100 m easy jog, walk the rest · Min 2: 10 reverse lunges each side · Min 4: 20 m bear crawl + 12 glute bridges"]}}, {"kind": "skill", "label": "Accessory", "title": "Core", "minutes": 6, "versions": ["2 rounds: 6 dead bugs each side, arms only · 15 s side plank from the knees each side", "2 rounds: 10 dead bugs each side · 20 s side plank from the knees each side", "2 rounds: 10 dead bugs each side · 20 s side plank each side", "2 rounds: 10 dead bugs each side · 20 s side plank each side"]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + log", "minutes": 8, "versions": ["3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s\nWrite your best set of 3 on your scorecard.", "3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s\nWrite your best set of 3 on your scorecard.", "3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s\nWrite your best set of 3 on your scorecard.", "3 min easy row · pigeon stretch 1 min each side · dead hang 3 × 15 s\nWrite your best set of 3 on your scorecard."]}]'::jsonb, 'published', null)
