insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-10', 'Accessory + Easy Intervals', 'Accessory strength · easy intervals', 'The easy day: strength work for joints and posture, then easy row and bike intervals. Nobody should breathe hard today.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 7, "versions": ["2 min easy bike · 10 deep-squat pries · 10 ankle rocks each side\n5 bodyweight split squats each side · 10 band face pulls · 20 s hollow hold", "2 min easy bike · 10 deep-squat pries · 10 ankle rocks each side\n5 bodyweight split squats each side · 10 band face pulls · 20 s hollow hold", "2 min easy bike · 10 deep-squat pries · 10 ankle rocks each side\n5 bodyweight split squats each side · 10 band face pulls · 20 s hollow hold", "2 min easy bike · 10 deep-squat pries · 10 ankle rocks each side\n5 bodyweight split squats each side · 10 band face pulls · 20 s hollow hold"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory strength + core", "minutes": 21, "versions": ["Light prep for Friday''s press test: 2 rounds\n8 light dumbbell rear-delt flys, chest on an incline bench · 8 light kettlebell deadlifts, bell on a low step · 6 dead bugs each side, arms only\nLeave 3–4 reps in the tank.", "Light prep for Friday''s press test: 2 rounds\n10 light dumbbell rear-delt flys · 10 light kettlebell deadlifts · 10 slow dead bugs each side\nLeave 3–4 reps in the tank.", "Light prep for Friday''s press test: 2 rounds\n10 light dumbbell rear-delt flys · 10 light kettlebell deadlifts · 10 dead bugs each side\nLeave 3–4 reps in the tank.", "Light prep for Friday''s press test: 2 rounds\n10 light dumbbell rear-delt flys · 10 light kettlebell deadlifts · 10 dead bugs each side\nLeave 3–4 reps in the tank."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Easy row/bike intervals", "minutes": 21, "versions": ["3 rounds: 4 min easy / 1 min rest (14 min), switch between row and air bike each round\nVery easy: talk in full sentences. Rounds can be 1–2 min shorter.\nNo machine free? Same clock, 1 min each: marching · low step-ups · wall push-ups.", "3 rounds: 4 min easy / 1 min rest (14 min), switch between row and air bike each round\nEasy and chatty: talk in full sentences. Rounds can be 1 min shorter.\nNo machine free? Same clock, 1 min each: step-ups to a low box · jumping jacks · air squats.", "3 rounds: 4 min easy / 1 min rest (14 min), switch between row and air bike each round\nEasy: talk in full sentences. Same pace every round.\nNo machine free? Same clock, 1 min each: step-ups · jumping jacks · air squats · easy single-unders.", "3 rounds: 4 min easy / 1 min rest (14 min), switch between row and air bike each round\nEasy: talk in full sentences. Same pace every round.\nNo machine free? Same clock, 1 min each: step-ups · jumping jacks · air squats · easy single-unders."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + mobility", "minutes": 8, "versions": ["3 min easy bike · couch stretch 1 min each side · adductor rocks · box breathing 1 min", "3 min easy bike · couch stretch 1 min each side · adductor rocks · box breathing 1 min", "3 min easy bike · couch stretch 1 min each side · adductor rocks · box breathing 1 min", "3 min easy bike · couch stretch 1 min each side · adductor rocks · box breathing 1 min"]}]'::jsonb, 'published', null)
