insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-11', 'Press Test + Station AMRAP', 'Press test · stations', 'Press retest, then the Week 1 station workout again, so you can compare both. The stations are steady, not all-out.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["2 min jump rope · 5 inchworm push-ups · 10 lunges\n7 min, empty bar: 5 hang power cleans · 5 push presses · 5 push jerks · then build-up sets", "2 min jump rope · 5 inchworm push-ups · 10 lunges\n7 min, empty bar: 5 hang power cleans · 5 push presses · 5 push jerks · then build-up sets", "2 min jump rope · 5 inchworm push-ups · 10 lunges\n7 min, empty bar: 5 hang power cleans · 5 push presses · 5 push jerks · then build-up sets", "2 min jump rope · 5 inchworm push-ups · 10 lunges\n7 min, empty bar: 5 hang power cleans · 5 push presses · 5 push jerks · then build-up sets"]}, {"kind": "strength", "label": "Test", "title": "Strict press test: heavy 5", "minutes": 17, "lift": {"movement": "Strict press", "gentleMovement": "Dumbbell press", "mode": "build", "sets": 1, "reps": 5, "pct": [null, null, null, null], "note": "No leg drive. Week 1 5RM × 1.13 = e1RM this block."}, "versions": ["Seated dumbbell press test: build to a heavy set of 5\nLight × 10, then 2 sets of 5, then 2–4 tries at 5. Stop at RPE 8 (2 reps left). 15 min.\nWrite down the weight per hand and the change from Week 1.", "Strict press test: build to a heavy set of 5\nEmpty bar × 10, then build in 5s, then 2–4 tries at 5, adding 2.5–5 lb each time. No leg drive, ribs down. 15 min.\nWrite down your weight and the change from Week 1.", "Strict press test: build to a heavy set of 5\nEmpty bar × 10, then build in 5s, then 2–4 tries at 5, adding 5 lb each time. No leg drive, ribs down. 15 min.\nWrite down your weight and the change from Week 1.", "Strict press test: build to a heavy set of 5\nEmpty bar × 10, then build in 5s, then 2–4 tries at 5, adding 5–10 lb each time. No leg drive, ribs down. 15 min.\nWrite down your weight and the change from Week 1."]}, {"kind": "conditioning", "label": "Test", "title": "Station AMRAP", "minutes": 16, "versions": ["As many rounds as you can in 10 min, steady:\n10 wall balls 4/6 lb, low target (7 ft) · 20 m farmers carry 2 × 13/18 lb · 10 step-ups to a low step · 4 incline step-back burpees + 2 long strides each\nWrite down rounds + reps and your level; compare with Week 1.", "As many rounds as you can in 10 min, steady:\n10 wall balls 6/10 lb, lower target · 20 m farmers carry 2 × 18/26 lb · 10 bodyweight lunges (total) · 4 step-back burpees + a broad jump each\nWrite down rounds + reps and your level; compare with Week 1.", "As many rounds as you can in 10 min, steady:\n10 wall balls 6/10 lb · 20 m farmers carry 2 × 26/35 lb · 10 sandbag lunges 22/33 lb (total) · 4 burpee broad jumps\nWrite down rounds + reps and your level; compare with Week 1.", "As many rounds as you can in 10 min, steady:\n10 wall balls 10/14 lb · 20 m farmers carry 2 × 35/53 lb · 10 sandbag lunges 22/44 lb (total) · 4 burpee broad jumps\nWrite down rounds + reps and your level; compare with Week 1."]}, {"kind": "skill", "label": "Accessory", "title": "Rear-delt fly + leg raise", "minutes": 4, "versions": ["2 rounds: 8 light dumbbell rear-delt flys, chest on an incline bench · 6 lying bent-knee raises\nLeave 3–4 reps in the tank.", "2 rounds: 10 light dumbbell rear-delt flys · 8 lying leg raises\nLeave 3 reps in the tank.", "2 rounds: 10 dumbbell rear-delt flys · 8 hanging knee raises\nLeave 3 reps in the tank.", "2 rounds: 10 dumbbell rear-delt flys · 8 hanging knee raises\nLeave 3 reps in the tank."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 8, "versions": ["3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min", "3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min", "3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min", "3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min"]}]'::jsonb, 'published', null)
