insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-14', 'Light Squat + Community AMRAP', 'Squat technique · steady AMRAP', 'Light squat practice, then a steady workout everyone does at their own level. A great day to bring a friend.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["400 m easy row or bike · 10 spiderman lunges with reach · 10 PVC pass-throughs\n8 slow goblet squats (3 s down) · 3 squat jumps · then your warm-up sets", "400 m easy row or bike · 10 spiderman lunges with reach · 10 PVC pass-throughs\n8 slow goblet squats (3 s down) · 3 squat jumps · then your warm-up sets", "400 m easy row or bike · 10 spiderman lunges with reach · 10 PVC pass-throughs\n8 slow goblet squats (3 s down) · 3 squat jumps · then your warm-up sets", "400 m easy row or bike · 10 spiderman lunges with reach · 10 PVC pass-throughs\n8 slow goblet squats (3 s down) · 3 squat jumps · then your warm-up sets"]}, {"kind": "strength", "label": "Strength", "title": "Back squat 3 × 5 (technique)", "minutes": 20, "lift": {"movement": "Back squat", "gentleMovement": "Goblet squat", "mode": "percent", "sets": 3, "reps": 5, "pct": [null, 65, 65, 65], "note": "Optional technique work, not a test."}, "versions": ["Goblet box squat: 3 × 6, very light\nOptional. 2 s pause on the box. Brace, knees out, stand up tall.", "Back squat: 3 × 5 @ 65%\nOptional technique work. 2 s pause at the bottom. Rest 90 s. Brace, knees out, same depth every rep. Keep it light.", "Back squat: 3 × 5 @ 65%\nOptional technique work. 2 s pause at the bottom. Rest 90 s. Brace, knees out, same depth every rep. Keep it light.", "Back squat: 3 × 5 @ 65%\nOptional technique work. 2 s pause at the bottom. Rest 90 s. Brace, knees out, same depth every rep. Keep it light."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Community AMRAP", "minutes": 15, "versions": ["As many rounds as you can in 20 min, steady, rest when you need to:\n5/6 cal row · 8 wall balls (4/6 lb, low target) · 8 Russian KB swings to chest height (13/18 lb)\nNo rower free? 20 s step-jacks or marching.", "As many rounds as you can in 20 min, steady pace:\n6/8 cal row · 12 wall balls (6/10 lb) · 12 KB swings (18/26 lb)\nNo rower free? 30 jumping jacks.", "As many rounds as you can in 20 min, steady pace:\n9/12 cal row · 12 wall balls (10/14 lb) · 12 KB swings (26/35 lb)\nNo rower free? 80 single-unders.", "As many rounds as you can in 20 min, steady pace:\n9/12 cal row · 12 wall balls (14/20 lb) · 12 KB swings (35/53 lb)\nNo rower free? 80 single-unders."]}, {"kind": "skill", "label": "Accessory", "title": "Squat + core superset", "minutes": 5, "versions": ["2 rounds: 8 very light goblet squats to a box · 6 lying bent-knee raises\nLeave 3–4 reps in the tank.", "2 rounds: 10 light goblet squats with a pause · 8 lying leg raises\nLeave 3 reps in the tank.", "2 rounds: 10 goblet squats with a pause · 8 hanging knee raises\nLeave 3 reps in the tank.", "2 rounds: 10 goblet squats with a pause · 8 hanging knee raises\nLeave 3 reps in the tank."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads.", "3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads.", "3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads.", "3 min easy bike · couch stretch 1 min each side · child''s pose 1 min\nLog your loads."]}]'::jsonb, 'published', null)
