insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-15', 'Toes-to-Bar Retest + Easy Bike', 'Toes-to-bar retest · easy bike flow', 'Retest your toes-to-bar skill and compare with Week 2. Then an easy bike flow keeps your legs fresh for Helen and the Mini Challenge.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 11, "versions": ["400 m easy row or jog · 10 cat-cows · 10 PVC pass-throughs\n20 s hollow hold · 10 arch rocks · 2 × 5 kip swings · 2 × 3 easy toes-to-bar or knee raises", "400 m easy row or jog · 10 cat-cows · 10 PVC pass-throughs\n20 s hollow hold · 10 arch rocks · 2 × 5 kip swings · 2 × 3 easy toes-to-bar or knee raises", "400 m easy row or jog · 10 cat-cows · 10 PVC pass-throughs\n20 s hollow hold · 10 arch rocks · 2 × 5 kip swings · 2 × 3 easy toes-to-bar or knee raises", "400 m easy row or jog · 10 cat-cows · 10 PVC pass-throughs\n20 s hollow hold · 10 arch rocks · 2 × 5 kip swings · 2 × 3 easy toes-to-bar or knee raises"]}, {"kind": "skill", "label": "Test", "title": "Toes-to-bar retest", "minutes": 13, "versions": ["Lying bent-knee raises: max unbroken, one try\nWarm up with 2 × 3 easy reps first.\nWrite down your max, your level and the change from Week 2.", "Hanging knee raises to hip height: max unbroken, one try\nWarm up with 3 × 3 easy hanging knee raises.\nWrite down your max, your level and the change from Week 2.", "Hanging knee raises to hip height: max unbroken, one try\nWarm up with 3 × 3 easy kipping knee raises.\nWrite down your max, your level and the change from Week 2.\nOptional: one set of max strict pull-ups. Write that down too.", "Toes-to-bar: max unbroken, one try\nWarm up with 3 × 3 easy toes-to-bar.\nWrite down your max, your level and the change from Week 2.\nOptional: one set of max strict pull-ups. Write that down too."]}, {"kind": "conditioning", "label": "Conditioning", "title": "Easy bike flow", "minutes": 28, "versions": ["4 easy rounds, not for time (about 20 min):\n2 min very easy air bike · 6 step-ups each leg to a low step (hold the rig) · 15 s side plank on knees, each side\nTalk-able pace. Bodyweight only: save your legs.\nNo bike free? 2 min easy marching or step-jacks.", "4 easy rounds, not for time (about 20 min):\n2½ min easy air bike · 8 step-ups each leg to a low box · 20 s side plank from the knees each side\nTalk-able pace. Bodyweight only: save your legs.\nNo bike free? 2½ min easy jumping jacks and marching.", "4 easy rounds, not for time (about 20 min):\n3 min easy air bike · 8 step-ups each leg to a knee-height box · 20 s side plank each side\nTalk-able pace. Bodyweight only: save your legs.\nNo bike free? 3 min easy single-unders and jumping jacks.", "4 easy rounds, not for time (about 20 min):\n3 min easy air bike · 10 step-ups each leg to a knee-height box · 30 s side plank each side\nTalk-able pace. Bodyweight only: save your legs.\nNo bike free? 3 min easy single-unders and jumping jacks."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 5, "versions": ["Walk 2 min · calf and hamstring stretch 1 min each side · lat stretch on the rig 1 min", "Walk 2 min · calf and hamstring stretch 1 min each side · lat stretch on the rig 1 min", "Walk 2 min · calf and hamstring stretch 1 min each side · lat stretch on the rig 1 min", "Walk 2 min · calf and hamstring stretch 1 min each side · lat stretch on the rig 1 min"]}]'::jsonb, 'published', null)
