insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-17', 'Accessories + Easy Intervals', 'Accessory strength · easy intervals', 'An easy day plus your scorecard: compare your Week 1 and Week 8 numbers and set one goal for the next block.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 7, "versions": ["2 min easy bike · 10 deep-squat pries · 10 ankle rocks each side\n5 bodyweight split squats each side · 10 band face pulls · 20 s hollow hold", "2 min easy bike · 10 deep-squat pries · 10 ankle rocks each side\n5 bodyweight split squats each side · 10 band face pulls · 20 s hollow hold", "2 min easy bike · 10 deep-squat pries · 10 ankle rocks each side\n5 bodyweight split squats each side · 10 band face pulls · 20 s hollow hold", "2 min easy bike · 10 deep-squat pries · 10 ankle rocks each side\n5 bodyweight split squats each side · 10 band face pulls · 20 s hollow hold"]}, {"kind": "skill", "label": "Accessory", "title": "Accessory strength + core", "minutes": 21, "versions": ["2 rounds, leave 3–4 reps in the tank:\n8 light dumbbell rear-delt flys, chest on an incline bench · 6 split squats each side, holding the rig, short range · 6 dead bugs each side, arms only · 10 calf raises holding the rig", "2 rounds, leave 3 reps in the tank:\n10 light dumbbell rear-delt flys · 10 bodyweight split squats each side (hold the rig) · 10 dead bugs each side · 15 calf raises", "2 rounds, leave 3 reps in the tank:\n10 dumbbell rear-delt flys · 10 dumbbell split squats each side · 10 dead bugs each side · 15 calf raises", "2 rounds, leave 3 reps in the tank:\n10 dumbbell rear-delt flys · 10 dumbbell split squats each side · 10 dead bugs each side · 15 calf raises"]}, {"kind": "conditioning", "label": "Conditioning", "title": "Easy row/bike intervals", "minutes": 21, "versions": ["4 rounds: 4 min easy, 1 min rest (19 min). Alternate row and air bike.\nVery easy, talk-able pace. Rounds can be 1–2 min shorter; slow pedalling is fine.\nNo machine free? Same clock, 1 min each: marching · step-ups to a low step · wall push-ups.", "4 rounds: 4 min easy, 1 min rest (19 min). Alternate row and air bike.\nEasy, chatty pace. Rounds can be 1 min shorter.\nNo machine free? Same clock, 1 min each: step-ups to a low box · jumping jacks · air squats.", "4 rounds: 4 min easy, 1 min rest (19 min). Alternate row and air bike.\nEasy, talk-able pace. Same pace every round.\nNo machine free? Same clock, 1 min each: step-ups · jumping jacks · air squats · easy single-unders.", "4 rounds: 4 min easy, 1 min rest (19 min). Alternate row and air bike.\nEasy but steady, still talk-able. Same pace every round.\nNo machine free? Same clock, 1 min each: step-ups · jumping jacks · air squats · easy single-unders."]}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down + mobility", "minutes": 8, "versions": ["3 min easy bike · couch stretch 1 min each side · adductor rocks · box breathing 1 min", "3 min easy bike · couch stretch 1 min each side · adductor rocks · box breathing 1 min", "3 min easy bike · couch stretch 1 min each side · adductor rocks · box breathing 1 min", "3 min easy bike · couch stretch 1 min each side · adductor rocks · box breathing 1 min"]}]'::jsonb, 'published', null)
