insert into public.workout_coach_notes (class_date, body) values ('2026-12-17', 'Flex week: every session is optional (members pick 3–4); guests and on-ramp members join at Steady (Foundations), or Gentle if they need an easier start. Scorecard review with a coach during the accessory block: about 5 min per small group; help each member write one goal for the next block. If there aren''t enough rowers and bikes, run the class in two waves: wave 1 does the intervals while wave 2 does the accessory strength, then swap at about minute 31; or send the overflow to the ''No machine free'' bodyweight rounds. The intervals have no outside version on purpose: Thursday is machine-only so weekly running volume stays as planned.
Scaling: Gentle warm-up: step instead of jumping, walk instead of jogging, comfortable range. Masters or injury: today is the best day for extra mobility or rehab work.
Interval targets: RPE Gentle 3–4, Steady 4, Strong 4–5, Full 5 (Zone 2: full sentences; if only a few words, slow down). Cap 19:00 (fixed) · Aim: same pace every round; Steady–Full row split 0:15–0:25 per 500 m slower than their 1 km test split, bike same calories each round (±1) · Feel cardio (easy) · Pace sustain.
No machine (warm-up/cool-down): jumping jacks, marching or jump rope, ~1:00 per 250 m or 5 cal.')
on conflict (class_date) do update set body = excluded.body, updated_at = now();
insert into public.workouts (class_date, title, focus, why, parts, status, created_by) values ('2026-12-18', 'Light Press + Mini Challenge', 'Press technique · Mini Challenge', 'Our Mini Challenge: 4 short runs or bike legs, each followed by a station. Your time is the baseline for the next block.', '[{"kind": "warmup", "label": "Warm-up", "title": "Warm-up", "minutes": 12, "versions": ["600 m easy jog or row · leg swings · arm circles\nwalk the course and standards, then 1 round at challenge pace, 10–15 s each: row · burpee broad jump · sandbag lunges · wall balls. Then 10 empty-bar strict presses.", "600 m easy jog or row · leg swings · arm circles\nwalk the course and standards, then 1 round at challenge pace, 10–15 s each: row · burpee broad jump · sandbag lunges · wall balls. Then 10 empty-bar strict presses.", "600 m easy jog or row · leg swings · arm circles\nwalk the course and standards, then 1 round at challenge pace, 10–15 s each: row · burpee broad jump · sandbag lunges · wall balls. Then 10 empty-bar strict presses.", "600 m easy jog or row · leg swings · arm circles\nwalk the course and standards, then 1 round at challenge pace, 10–15 s each: row · burpee broad jump · sandbag lunges · wall balls. Then 10 empty-bar strict presses."]}, {"kind": "strength", "label": "Strength", "title": "Strict press 3 × 5 (technique)", "minutes": 7, "lift": {"movement": "Strict press", "gentleMovement": "Dumbbell press", "mode": "percent", "sets": 3, "reps": 5, "pct": [null, 60, 60, 60], "note": "Optional technique work, not a test."}, "versions": ["Seated dumbbell press: 2 × 8, light\nOptional. Add 2 × 8 light dumbbell rear-delt flys.", "Strict press: 3 × 5 @ 60%\nOptional. Smooth reps, rest 90 s. Add 2 × 10 dumbbell rear-delt flys.", "Strict press: 3 × 5 @ 60%\nOptional. Smooth reps, rest 90 s. Add 2 × 10 dumbbell rear-delt flys.", "Strict press: 3 × 5 @ 60%\nOptional. Smooth reps, rest 90 s. Add 2 × 10 dumbbell rear-delt flys."]}, {"kind": "conditioning", "label": "Test", "title": "Mini Challenge (bike version)", "minutes": 30, "versions": ["For time, 26 min cap. 8/10 cal bike before each:\n200 m row · 10 step-back burpees (hands on box) · 16 low step-ups · 20 wall balls (4/6 lb, low target)\nEasy pace.\nNo machine? Row → 50 s step-jacks, bike → 35 s.\nLog time, level, leg 1 + 4 splits, run or bike.", "For time, 26 min cap. 12/15 cal bike before each:\n300 m row · 20 m step-back burpee broad jumps · 30 lunges (13/22 lb sandbag optional) · 30 wall balls (6/10 lb)\nNo machine? Row → 75 jumping jacks, bike → 55.\nLog time, level, leg 1 + 4 splits, run or bike.", "For time, 26 min cap. 16/20 cal bike before each:\n500 m row · 20 m burpee broad jumps · 30 sandbag lunges (22/33 lb) · 40 wall balls (6/10 lb, 9 ft)\nNo machine? Row → 250 single-unders, bike → 140.\nLog time, level, leg 1 + 4 splits, run or bike.", "For time, 26 min cap. 16/20 cal bike before each:\n500 m row · 20 m burpee broad jumps · 30 sandbag lunges (22/44 lb) · 40 wall balls (10/14 lb, 9/10 ft)\nNo machine? Row → 250 single-unders, bike → 140.\nLog time, level, leg 1 + 4 splits, run or bike."], "outdoor": {"title": "Mini Challenge", "versions": ["For time, 26 min cap. 200 m walk/jog before each:\n200 m row · 10 step-back burpees (hands on box) · 16 low step-ups · 20 wall balls (4/6 lb, low target)\nEasy pace.\nNo rower free? 150 m walk/jog instead.\nLog time, level, leg 1 + 4 splits, run or bike.", "For time, 26 min cap. 300 m run before each:\n300 m row · 20 m step-back burpee broad jumps · 30 lunges (13/22 lb sandbag optional) · 30 wall balls (6/10 lb)\nNo rower free? 250 m run instead.\nLog time, level, leg 1 + 4 splits, run or bike.", "For time, 26 min cap. 400 m run before each:\n500 m row · 20 m burpee broad jumps · 30 sandbag lunges (22/33 lb) · 40 wall balls (6/10 lb, 9 ft)\nNo rower free? 400 m run instead.\nLog time, level, leg 1 + 4 splits, run or bike.", "For time, 26 min cap. 400 m run before each:\n500 m row · 20 m burpee broad jumps · 30 sandbag lunges (22/44 lb) · 40 wall balls (10/14 lb, 9/10 ft)\nNo rower free? 400 m run instead.\nLog time, level, leg 1 + 4 splits, run or bike."]}}, {"kind": "cooldown", "label": "Cool-down", "title": "Cool-down", "minutes": 8, "versions": ["3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min", "3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min", "3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min", "3 min easy bike · doorway chest stretch 1 min each side · box breathing 1 min"]}]'::jsonb, 'published', null)
